L["ABOUT_TEXT"] = "LazyGCore suggère votre prochaine technique à l'aide de listes de priorités World of Warcraft: Forever étudiées pour les neuf classes, et guide vos choix de talents.\n\nForever fonctionne sur le moteur moderne de WoW, qui cache certaines informations de combat aux addons (vie de la cible, certaines auras, le journal de combat). LazyGCore lit tout via une couche sécurisée : quand le jeu cache une valeur, LazyGCore se rabat sur son propre suivi des incantations ou sur les vérifications « utilisable » de Blizzard au lieu de deviner.\n\nSi une suggestion semble fausse, passez le moteur sur « LazyGCore + secours Blizzard » ou « Combat assisté Blizzard », et utilisez /lazygcore check et /lazygcore status pour signaler ce que votre client affiche.\n\nCommandes : /lazygcore, /lazygcore talents, /lazygcore toggle, /lazygcore spec <name / auto>, /lazygcore engine <lazygcore / hybrid / blizzard>."

