L["Hard-hitting filler with Improved Starfire."] = "Sort de remplissage puissant avec Feu stellaire amélioré."
L["Threat on every mob, less damage taken."] = "Menace sur chaque monstre, moins de dégâts subis."

L["Cheetah / Pack is on in combat: every hit dazes you."] = "Guépard / Meute actif en combat : chaque coup vous hébète."
L["You have aggro - drop threat."] = "Vous avez l'aggro - réduisez la menace."
L["Melee: more dodge, and dodges enable Mongoose Bite."] = "Mêlée : plus d'esquive, et les esquives permettent la Morsure de la mangouste."
L["Group health hidden - mouse over who to heal"] = "Vie du groupe masquée - survolez la personne à soigner"
L["Immune to attacks and spells for 6-8s, but you can't attack; Forbearance after."] = "Immunisé aux attaques et sorts pendant 6-8 s, mais vous ne pouvez pas attaquer ; Longanimité ensuite."
L["Hard hits incoming: +30% block for 10s."] = "Gros coups à venir : +30 % de blocage pendant 10 s."
L["+30% block; every block deals Holy damage and threat to the pack."] = "+30 % de blocage ; chaque blocage inflige des dégâts du Sacré et de la menace au pack."
L["Instant damage between Auto Shots."] = "Dégâts instantanés entre les Tirs automatiques."
L["Out of melee: sting it while you close in."] = "Hors de la mêlée : posez la morsure pendant que vous approchez."
L["Hit plus a Fire DoT."] = "Coup plus un DoT de feu."
L["One more DoT while the target lives long enough."] = "Un DoT de plus tant que la cible vit assez longtemps."
L["Heal up between pulls."] = "Soignez-vous entre les packs."
L["Pack is down - back to Cat."] = "Le pack est mort - retour en félin."
L["You tank this group: Bear Form."] = "Vous tankez ce groupe : forme d'ours."
L["Feral in groups:"] = "Farouche en groupe :"
L["Bear (tank)"] = "Ours (tank)"
L["Cat (damage)"] = "Félin (dégâts)"
L["Pool energy for Ghostly Strike."] = "Accumulez de l'énergie pour Frappe fantomatique."
L["Renew yourself: heals over 15s while you keep casting."] = "Rénovation sur vous : soigne pendant 15 s pendant que vous continuez à lancer."
L["Instant hit plus a 12s Fire DoT."] = "Coup instantané plus un DoT de Feu de 12 s."
L["Regrowth is ticking - Healing Touch for the rest."] = "Rétablissement est actif - Toucher guérisseur pour le reste."
L["Low health: absorb the next hits."] = "Vie basse : absorbez les prochains coups."
L["Your main nuke."] = "Votre sort de dégâts principal."
L["Damage and a 40% slow on everything in front of you."] = "Dégâts et ralentissement de 40 % sur tout ce qui est devant vous."
L["Shadow DoT: keep it ticking."] = "DoT d'Ombre : gardez-le actif."
L["Channeled: hits everything in the area for 6s."] = "Canalisé : touche tout dans la zone pendant 6 s."
L["At your feet: Fire damage to every mob within 10 yd."] = "À vos pieds : dégâts de Feu à tous les ennemis à 10 m."
L["At your feet: burns the first mob to reach it."] = "À vos pieds : brûle le premier ennemi qui l'atteint."
L["Weapon-damage kick, 8s cooldown (+30% run speed)."] = "Coup de pied aux dégâts d'arme, 8 s de recharge (+30 % de vitesse)."
L["21s bleed: keep it on targets that live."] = "Saignement de 21 s : maintenez-le sur les cibles qui durent."
L["Single target: your hardest-hitting shot."] = "Cible unique : votre tir le plus puissant."
L["Hits up to 4 enemies around you."] = "Touche jusqu'à 4 ennemis autour de vous."
L["Open with Charge, then Berserker Stance."] = "Ouvrez par une Charge, puis Posture berserker."
L["Before Whirlwind (36) Fury fights here: Rend and Overpower."] = "Avant Tourbillon (36), Fureur combat ici : Pourfendre et Fulgurance."
L["Pool energy for Backstab."] = "Accumulez de l'énergie pour Attaque sournoise."
L["In danger: quick heal on yourself."] = "En danger : soin rapide sur vous-même."
L["Hurt: Renew yourself and keep casting."] = "Blessé : Rénovation sur vous et continuez à lancer."
L["Shadowform filler."] = "Sort de remplissage en Forme d'Ombre."
L["Filler: out-damages the wand."] = "Sort de remplissage : fait plus de dégâts que la baguette."
L["Group health hidden: a cheap heal on the tank (mouse over whoever needs it)."] = "Vie du groupe masquée : un soin peu coûteux sur le tank (survolez celui qui en a besoin)."
-- ============================================================================
-- OPTION TOOLTIPS (hover explanations of the options window controls)
-- ============================================================================
L["Turns LazyGCore on or off. Off hides the display and stops all suggestions, action bar glows, alerts and sounds."] = "Active ou désactive LazyGCore. Désactivé, l'affichage est masqué et toutes les suggestions, lueurs de barre d'action, alertes et sons s'arrêtent."
L["Keeps the display where it is. While locked the icon ignores the mouse, so clicks pass through to the game; unlock it to drag the display somewhere else."] = "Garde l'affichage en place. Verrouillée, l'icône ignore la souris et les clics passent au jeu ; déverrouillez-la pour déplacer l'affichage ailleurs."
L["Shows the LazyGCore button on the minimap. Click: these options. Ctrl+Click: show or hide the display. Shift+Click: Stats window. Alt+Click: talents."] = "Affiche le bouton LazyGCore sur la minicarte. Clic : ces options. Ctrl+Clic : afficher ou masquer l'affichage. Maj+Clic : fenêtre Stats. Alt+Clic : talents."
L["Where the suggestions come from. LazyGCore priorities: LazyGCore's own rotation for your spec. LazyGCore + Blizzard fallback: LazyGCore first, and only when LazyGCore has nothing to suggest, Blizzard's Assisted Combat pick is shown. Blizzard Assisted Combat: Blizzard's pick on the main icon, LazyGCore's next spells in the queue."] = "Origine des suggestions. Priorités LazyGCore : la rotation propre à LazyGCore pour votre spécialisation. LazyGCore + secours Blizzard : LazyGCore d'abord, et le choix du Combat assisté Blizzard n'apparaît que lorsque LazyGCore n'a rien à suggérer. Combat assisté Blizzard : le choix de Blizzard sur l'icône principale, les sorts suivants de LazyGCore dans la file."
L["Which spec's rotation LazyGCore follows on this character. Auto picks the talent tree with the most points (the Leveling rotation before you spend any). Pick a spec to force it; it goes back to Auto when you switch talent specs."] = "La rotation de spécialisation que LazyGCore suit sur ce personnage. Auto choisit l'arbre de talents le plus investi (la rotation Montée en niveau tant qu'aucun point n'est dépensé). Choisissez une spécialisation pour la forcer ; elle repasse sur Auto quand vous changez de spécialisation de talents."
L["Shows the rotation display. Off hides it (with its alerts) everywhere, even in combat, while the action bar glow keeps following the suggestions. Same as /lazygcore toggle."] = "Montre l'affichage de rotation. Désactivé, il est masqué partout (avec ses alertes), même en combat, mais la lueur de la barre d'action continue de suivre les suggestions. Identique à /lazygcore toggle."
L["Keeps the display on screen out of combat too. Off (default): it shows in combat, plus the two cases below."] = "Garde aussi l'affichage à l'écran hors combat. Désactivé (par défaut) : il apparaît en combat, ainsi que dans les deux cas ci-dessous."
L["Out of combat, also show the display while you target an enemy, so you see the opener before the pull. Only applies when Show out of combat is off."] = "Hors combat, montre aussi l'affichage quand vous ciblez un ennemi, pour voir l'ouverture avant le pull. Seulement si l'option Afficher hors combat est désactivée."
L["Out of combat, also show the display when it suggests a missing buff, pet, poison or weapon imbue, and hide it again once done. Only applies when Show out of combat is off and Suggest buffs & pets (Combat page) is on."] = "Hors combat, montre aussi l'affichage quand il suggère un buff, un familier, un poison ou un enchantement d'arme manquant, puis le masque une fois fait. Seulement si l'option Afficher hors combat est désactivée et Suggérer buffs et familiers (page Combat) activée."
L["Out of combat, hide the display while there is nothing to suggest instead of showing the LazyGCore logo. Only applies when Show out of combat is on."] = "Hors combat, masque l'affichage quand il n'y a rien à suggérer au lieu de montrer le logo LazyGCore. Seulement si l'option Afficher hors combat est activée."
L["Shows the spell part of the display: main icon, cooldown icon, history, queue, spell name and reason. Off hides those; the ring (swing timer), warning line, alerts, buff tracker and DPS strip stay, and the action bar glow still works."] = "Montre la partie sorts de l'affichage : icône principale, icône de recharge, historique, file, nom du sort et raison. Désactivé, ils sont masqués ; l'anneau (chrono de frappe), la ligne d'avertissement, les alertes, le suivi des buffs et le bandeau DPS restent, et la lueur de la barre d'action fonctionne toujours."
L["Color of the ring around the main icon, the DPS strip accent and the Auto action bar glow. Auto (Match Spec) uses your spec's color."] = "Couleur de l'anneau autour de l'icône principale, de l'accent du bandeau DPS et de la lueur Auto de la barre d'action. Auto (Selon Spé) utilise la couleur de votre spécialisation."
L["Look of LazyGCore's windows: these options, the Stats window and the talent windows. Default is the classic WoW gold style."] = "Apparence des fenêtres de LazyGCore : ces options, la fenêtre Stats et les fenêtres de talents. Par défaut : le style doré classique de WoW."
L["Size of the whole rotation display: icons, text and DPS strip. Does not change LazyGCore's windows. Default 1.0."] = "Taille de tout l'affichage de rotation : icônes, texte et bandeau DPS. Ne change pas les fenêtres de LazyGCore. Par défaut 1.0."
L["Size of the main spell icon in pixels, before Scale. The cooldown icon grows with it. Default 72."] = "Taille de l'icône du sort principal en pixels, avant l'Échelle. L'icône de recharge grandit avec elle. Par défaut 72."
L["Opacity of the whole rotation display: icons, text, warning line, alerts and DPS strip. 1 = fully visible."] = "Opacité de tout l'affichage de rotation : icônes, texte, ligne d'alerte, alertes et bandeau DPS. 1 = entièrement visible."
L["Opacity of the spell icons only: the main icon and its ring, the cooldown icon, the spell history and the queue (NEXT). The text stays fully visible."] = "Opacité des icônes de sorts uniquement : l'icône principale et son anneau, l'icône de recharge, l'historique des sorts et la file (SUIV). Le texte reste entièrement visible."
L["Dark box behind the rotation display. 0 (default) = no box; higher = a more solid box."] = "Fond sombre derrière l'affichage de rotation. 0 (par défaut) = aucun fond ; plus haut = un fond plus opaque."
L["Moves the rotation display back to its default spot below the middle of the screen."] = "Replace l'affichage de rotation à sa position par défaut, sous le centre de l'écran."
L["Sets Spec template back to Auto and detects your spec from your talents again."] = "Remet Modèle de spécialisation sur Auto et détecte à nouveau votre spécialisation d'après vos talents."
L["Opens or closes the floating Stats window (DPS, parse estimate, live stats)."] = "Ouvre ou ferme la fenêtre flottante Stats (DPS, estimation de parse, stats en direct)."
L["Opens or closes the Talent Guide window with the recommended talent build for your spec."] = "Ouvre ou ferme la fenêtre Guide des talents avec le build de talents recommandé pour votre spécialisation."
L["Shows the key bound to the suggested spell in the top-right corner of the main icon, read from your action bars."] = "Affiche la touche liée au sort suggéré dans le coin supérieur droit de l'icône principale, lue depuis vos barres d'action."
L["Shows a gold star in the top-left corner of the main icon when the suggestion comes from a proc."] = "Affiche une étoile dorée dans le coin supérieur gauche de l'icône principale quand la suggestion vient d'un proc."
L["Shows 'Out of Range' over the main icon and greys it out when your target is out of range of the suggested spell."] = "Affiche 'Hors de portée' sur l'icône principale et la grise quand votre cible est hors de portée du sort suggéré."
L["Shows a badge with the enemy count in the bottom-left corner of the main icon when enough enemies are near for AoE."] = "Affiche un badge avec le nombre d'ennemis dans le coin inférieur gauche de l'icône principale quand assez d'ennemis sont proches pour l'AoE."
L["Shows the global cooldown sweep over the main icon after each cast. Off by default."] = "Affiche le balayage du temps de recharge global sur l'icône principale après chaque sort. Désactivé par défaut."
L["Healers: shows the name of the group member a heal is suggested for at the bottom of the main icon (not for yourself or your target)."] = "Soigneurs : affiche en bas de l'icône principale le nom du membre du groupe pour qui un soin est suggéré (pas pour vous ni pour votre cible)."
L["Shows a smaller icon right of the main icon for your next major cooldown, racial or on-use trinket: green pulse when ready, grey while it recharges. Off: cooldowns go into the queue instead."] = "Affiche une petite icône à droite de l'icône principale pour votre prochain grand temps de recharge, racial ou bijou à utiliser : pulsation verte quand il est prêt, grise pendant la recharge. Désactivé : les temps de recharge vont dans la file."
L["Size of the cooldown icon compared to the main icon (0.65 = 65%). Only applies when Cooldown icon is on."] = "Taille de l'icône de recharge par rapport à l'icône principale (0.65 = 65 %). Seulement si l'option Icône de recharge est activée."
L["Shows your last casts as small icons left of the main icon (PREV), newest nearest to it."] = "Affiche vos derniers sorts en petites icônes à gauche de l'icône principale (PRÉC), le plus récent au plus près."
L["How many past casts to show. Only applies when Spell history is on."] = "Nombre de sorts passés à afficher. Seulement si l'option Historique des sorts est activée."
L["Size of the history icons in pixels. Only applies when Spell history is on."] = "Taille des icônes d'historique en pixels. Seulement si l'option Historique des sorts est activée."
L["On (default): history, main icon, cooldown icon and queue sit in one row. Off: the classic layout with the queue under the spell name."] = "Activé (par défaut) : historique, icône principale, icône de recharge et file sur une seule ligne. Désactivé : la disposition classique avec la file sous le nom du sort."
L["Shows the spells LazyGCore expects to suggest after the current one (NEXT)."] = "Affiche les sorts que LazyGCore prévoit de suggérer après le sort actuel (SUIV)."
L["How many upcoming spells to show. Only applies when Priority queue is on."] = "Nombre de sorts à venir à afficher. Seulement si l'option File de priorité est activée."
L["Size of the queue icons in pixels. Only applies when Priority queue is on."] = "Taille des icônes de la file en pixels. Seulement si l'option File de priorité est activée."
L["Shows the name of the suggested spell under the main icon."] = "Affiche le nom du sort suggéré sous l'icône principale."
L["Shows a short reason under the spell name: why this spell is suggested now, or why the rotation is paused."] = "Affiche une courte raison sous le nom du sort : pourquoi ce sort est suggéré maintenant, ou pourquoi la rotation est en pause."
L["Hides the spell name, the reason text and the DPS strip in one go (in the classic layout also the queue), whatever their own toggles say. Same as /lazygcore hidename."] = "Masque d'un coup le nom du sort, le texte de raison et le bandeau DPS (dans la disposition classique, la file aussi), quels que soient leurs propres réglages. Identique à /lazygcore hidename."
L["Shows a health bar for your target above the main icon."] = "Affiche une barre de vie de votre cible au-dessus de l'icône principale."
L["Shows the warning line above the icon: buff reminders, a suggested spell missing from your action bars, a lower rank on your bars, a paused rotation. Off hides all of them."] = "Affiche la ligne d'alerte au-dessus de l'icône : rappels de buffs, sort suggéré absent de vos barres d'action, rang inférieur sur vos barres, rotation en pause. Désactivé, tout cela est masqué."
L["Out of combat, the warning line names a missing buff ('Recommended: ...') or one about to run out, with its time left. Only applies when Warning line is on."] = "Hors combat, la ligne d'alerte nomme un buff manquant ('Recommandé : ...') ou sur le point d'expirer, avec son temps restant. Seulement si l'option Ligne d'alerte est activée."
L["Out of combat, the warning line lists up to three missing buffs ('Missing: ...') instead of naming only one. Only applies when Warning line is on."] = "Hors combat, la ligne d'alerte liste jusqu'à trois buffs manquants ('Manque : ...') au lieu d'en nommer un seul. Seulement si l'option Ligne d'alerte est activée."
L["Shows a row of small icons under the display with your important buffs and your damage over time spells on the target, with their time left."] = "Affiche sous l'affichage une rangée de petites icônes avec vos buffs importants et vos sorts de dégâts sur la durée sur la cible, avec leur temps restant."
L["Puts your active procs (Clearcasting, Shadow Trance, ...) first in the buff tracker. Only applies when Buff tracker is on."] = "Place vos procs actifs (Idées claires, Transe de l'ombre, ...) en premier dans le suivi des buffs. Seulement si l'option Suivi des buffs est activée."
L["Fades the display while there is nothing to suggest. How far is set by Idle Transparency."] = "Estompe l'affichage quand il n'y a rien à suggérer. L'intensité se règle avec Transparence au repos."
L["Shows your melee swing (Hunters: Auto Shot) on the ring around the main icon; it pulses when the next swing is ready. Only applies when Show outline is on."] = "Affiche votre coup de mêlée (Chasseurs : Tir automatique) sur l'anneau autour de l'icône principale ; il pulse quand le prochain coup est prêt. Seulement si l'option Afficher le contour est activée."
L["How visible the display stays while idle, as a share of Overall Transparency (0.3 = 30%). Only applies when Fade when idle is on."] = "Visibilité de l'affichage au repos, en part de la Transparence générale (0.3 = 30 %). Seulement si l'option Estomper au repos est activée."
L["Makes the action bar button of the suggested spell glow, so you find it at a glance."] = "Fait briller le bouton de barre d'action du sort suggéré, pour le repérer d'un coup d'œil."
L["Look of that glow: LazyGCore glow (soft breathing glow), Marching ants, or Blizzard's own proc glow. Only applies when Glow the suggested spell is on."] = "Aspect de cette lueur : Lueur LazyGCore (lueur douce qui respire), Fourmis, ou la lueur de proc de Blizzard. Seulement si l'option Faire briller le sort suggéré est activée."
L["Color of that glow. Auto (Match Spec) uses your theme color. Only applies when Glow the suggested spell is on."] = "Couleur de cette lueur. Auto (Selon Spé) utilise la couleur de votre thème. Seulement si l'option Faire briller le sort suggéré est activée."
L["When the suggested spell is not on your action bars, the spellbook button and the spell inside the spellbook glow, so you can drag it to a bar."] = "Quand le sort suggéré n'est pas sur vos barres d'action, le bouton du grimoire et le sort dans le grimoire brillent, pour que vous puissiez le glisser sur une barre."
L["When a bar button holds a lower rank of the suggested spell, its glow turns orange and the warning line says which rank to put there."] = "Quand un bouton de barre contient un rang inférieur du sort suggéré, sa lueur devient orange et la ligne d'alerte indique quel rang y placer."
L["Makes the action bar buttons of your spec's major cooldowns glow whenever they are ready, separately from the glow on the suggested spell."] = "Fait briller les boutons de barre d'action des grands temps de recharge de votre spécialisation dès qu'ils sont prêts, indépendamment de la lueur du sort suggéré."
L["Color of the cooldown glow (default green). Only applies when Enable Cooldown Glow is on."] = "Couleur de la lueur de recharge (vert par défaut). Seulement si l'option Activer la lueur de recharge est activée."
L["Adds swing bars inside the main icon: main hand (gold), off hand (blue) and ranged (green, GO when ready)."] = "Ajoute des barres de frappe dans l'icône principale : main droite (or), main gauche (bleu) et distance (vert, GO quand prêt)."
L["Starts or stops a test swing so you can see the swing timer without fighting."] = "Lance ou arrête une frappe de test pour voir le chrono de frappe sans combattre."
L["Includes your major offensive cooldowns, racials and on-use trinkets in the suggestions (in combat, with a target)."] = "Inclut vos grands temps de recharge offensifs, raciaux et bijoux à utiliser dans les suggestions (en combat, avec une cible)."
L["Suggests defensive spells and escapes when you are in danger: low health, stunned or feared. Also needed for the heal-your-pet and mana gem suggestions."] = "Suggère des sorts défensifs et des fuites quand vous êtes en danger : vie basse, étourdi ou apeuré. Nécessaire aussi pour les suggestions de soin du familier et de gemme de mana."
L["Out of combat, the main icon suggests missing self-buffs, poisons and weapon imbues, calling or reviving your pet, and healing up between pulls."] = "Hors combat, l'icône principale suggère les buffs personnels, poisons et enchantements d'arme manquants, l'appel ou la résurrection de votre familier, et la récupération de vie entre les pulls."
L["Lets LazyGCore switch to your spec's AoE spells when at least AoE enemy threshold enemies are near."] = "Permet à LazyGCore de passer aux sorts de zone de votre spécialisation quand le nombre d'ennemis proches atteint le Seuil d'ennemis pour la zone."
L["Allows AoE suggestions in battlegrounds and against players. Off by default, because every nearby player counts as an enemy. Only applies when Enable AoE suggestions is on."] = "Autorise les suggestions AoE en champ de bataille et contre des joueurs. Désactivé par défaut, car chaque joueur proche compte comme un ennemi. Seulement si l'option Activer les suggestions AoE est activée."
L["How many enemies are needed for AoE suggestions (default 3). LazyGCore counts living enemies in combat within about 10 yards, or in range of your ranged AoE spell, from their nameplates, so enemy nameplates must be on."] = "Nombre d'ennemis requis pour les suggestions AoE (3 par défaut). LazyGCore compte les ennemis vivants en combat à environ 10 mètres, ou à portée de votre sort de zone à distance, grâce à leurs barres de nom : les barres de nom ennemies doivent être activées."
L["Keeps the current suggestion for 0.3 seconds when another spell would briefly take over, so the icon doesn't flicker. Defensives always switch at once."] = "Garde la suggestion actuelle 0,3 seconde quand un autre sort prendrait brièvement le relais, pour éviter que l'icône clignote. Les défensifs changent toujours immédiatement."
L["Suggests your race's abilities, such as Berserking or Stoneform, along with your other spells."] = "Suggère les techniques de votre race, comme Berserker ou Forme de pierre, avec vos autres sorts."
L["Shows ready on-use trinkets in the cooldown slot, and your PvP trinket when you are stunned or feared (with Suggest defensives on)."] = "Affiche les bijoux à utiliser prêts dans l'emplacement de recharge, et votre bijou JcJ quand vous êtes étourdi ou apeuré (avec Suggérer les défensifs activé)."
L["Healers: never suggest damage spells, not even solo."] = "Soigneurs : ne jamais suggérer de sorts de dégâts, même en solo."
L["Healers in a group: suggest damage spells while nobody needs healing. Solo, healers always get damage suggestions."] = "Soigneurs en groupe : suggérer des sorts de dégâts tant que personne n'a besoin de soins. En solo, les soigneurs reçoivent toujours des suggestions de dégâts."
L["Healers: heal suggestions are for the friendly player under your mouse when there is one. Changes the suggestion target only - it never targets anything."] = "Soigneurs : les suggestions de soin visent le joueur allié sous votre souris s'il y en a un. Ne change que la cible de la suggestion - LazyGCore ne cible jamais rien."
L["Shows a KICK! box to the left of the icon (left of the spell history when it shows) when your enemy target casts something you can interrupt and your interrupt is ready."] = "Affiche un cadre KICK ! à gauche de l'icône (à gauche de l'historique des sorts quand il est affiché) quand votre cible ennemie lance un sort interruptible et que votre interruption est prête."
L["Shows a DEFENSIVE! box in combat when your health drops below Defensive Threshold and a defensive spell is ready."] = "Affiche un cadre DÉFENSIVE ! en combat quand votre vie passe sous le Seuil défensif et qu'un sort défensif est prêt."
L["Your health % below which the DEFENSIVE! box appears (default 35%). Only applies when Defensive Alerts is on."] = "Votre % de vie sous lequel le cadre DÉFENSIVE ! apparaît (35 % par défaut). Seulement si l'option Alertes défensives est activée."
L["Out of combat, shows a PURGE box when your enemy target has a magic buff and your purge or dispel is ready."] = "Hors combat, affiche un cadre PURGE quand votre cible ennemie a un buff magique et que votre purge ou dissipation est prête."
L["Shows EXECUTE! on the main icon while your enemy target is below Execute threshold. Only if you know Execute, Hammer of Wrath or Shadow Word: Death."] = "Affiche EXÉCUTION ! sur l'icône principale tant que votre cible ennemie est sous le Seuil d'exécution. Uniquement si vous connaissez Exécution, Marteau de courroux ou Mot de l'ombre : Mort."
L["Target health % below which EXECUTE! shows (default 20%). Only applies when Execute phase is on."] = "% de vie de la cible sous lequel EXÉCUTION ! s'affiche (20 % par défaut). Seulement si l'option Phase d'exécution est activée."
L["In combat, warns above the icon when your mana, rage or energy (and your pet's health) drops below the thresholds below."] = "En combat, avertit au-dessus de l'icône quand votre mana, rage ou énergie (et la vie de votre familier) passe sous les seuils ci-dessous."
L["Mana % below which the low mana warning shows (default 20%). Only applies when Low resource warnings is on."] = "% de mana sous lequel l'avertissement de mana bas s'affiche (20 % par défaut). Seulement si l'option Avertissements de ressource basse est activée."
L["Rage below which the low rage warning shows (default 20). Only applies when Low resource warnings is on."] = "Rage sous laquelle l'avertissement de rage basse s'affiche (20 par défaut). Seulement si l'option Avertissements de ressource basse est activée."
L["Energy below which the low energy warning shows (default 30). Only applies when Low resource warnings is on."] = "Énergie sous laquelle l'avertissement d'énergie basse s'affiche (30 par défaut). Seulement si l'option Avertissements de ressource basse est activée."
L["Pet health % below which the pet warning shows (default 30%). Only applies when Low resource warnings is on."] = "% de vie du familier sous lequel l'avertissement du familier s'affiche (30 % par défaut). Seulement si l'option Avertissements de ressource basse est activée."
L["Shows the KICK! box for 3 seconds so you can see where it appears."] = "Affiche le cadre KICK ! pendant 3 secondes pour voir où il apparaît."
L["Shows the DEFENSIVE! box for 3 seconds so you can see where it appears."] = "Affiche le cadre DÉFENSIVE ! pendant 3 secondes pour voir où il apparaît."
L["Shows the PURGE box for 3 seconds so you can see where it appears."] = "Affiche le cadre PURGE pendant 3 secondes pour voir où il apparaît."
L["Plays the alert sound when a KICK!, DEFENSIVE! or PURGE box appears, on low resource warnings and when a buff goes missing. Off by default."] = "Joue le son d'alerte quand un cadre KICK !, DÉFENSIVE ! ou PURGE apparaît, lors des avertissements de ressource basse et quand un buff manque. Désactivé par défaut."
L["Silences every sound LazyGCore plays, including the proc and weapon buff sounds."] = "Coupe tous les sons de LazyGCore, y compris ceux des procs et des buffs d'arme."
L["Plays a sound when a proc becomes the suggestion. Works even with Sound alerts off."] = "Joue un son quand un proc devient la suggestion. Fonctionne même quand l'option Alertes sonores est désactivée."
L["Which sound the alerts play. Only applies when Sound alerts is on."] = "Son joué par les alertes. Seulement si l'option Alertes sonores est activée."
L["Plays the chosen alert sound once."] = "Joue une fois le son d'alerte choisi."
L["How often suggestions are recalculated in combat. Faster reacts sooner but uses more CPU; casts, cooldowns and target changes refresh at once anyway. Default 20 per second."] = "Fréquence de recalcul des suggestions en combat. Plus rapide réagit plus tôt mais utilise plus de CPU ; les sorts lancés, temps de recharge et changements de cible actualisent de toute façon immédiatement. Par défaut 20 par seconde."
L["How often suggestions are recalculated out of combat. Slower saves CPU between fights; it is never faster than Update rate. Default 2 per second."] = "Fréquence de recalcul des suggestions hors combat. Plus lent économise du CPU entre les combats ; jamais plus rapide que la Fréquence de mise à jour. Par défaut 2 par seconde."
L["Prints extra diagnostic messages to chat. Errors are reported either way; leave this off unless you are tracking down a problem."] = "Affiche des messages de diagnostic supplémentaires dans le chat. Les erreurs sont signalées dans tous les cas ; laissez désactivé sauf pour traquer un problème."
L["Prints LazyGCore's status to chat: version, class, spec, engine and the settings that affect suggestions. Useful for bug reports."] = "Affiche l'état de LazyGCore dans le chat : version, classe, spécialisation, moteur et réglages qui influencent les suggestions. Utile pour les rapports de bug."
L["Prints which spells of your class rotation you know and which are still missing from your spellbook."] = "Affiche dans le chat les sorts de votre rotation de classe que vous connaissez et ceux qui manquent encore dans votre grimoire."
L["Turns on the game's Lua error pop-ups, to see errors from any addon."] = "Active les fenêtres d'erreurs Lua du jeu, pour voir les erreurs de n'importe quel addon."
L["Turns off the game's Lua error pop-ups."] = "Désactive les fenêtres d'erreurs Lua du jeu."
L["Prints the buffs and procs the buff tracker watches for your spec to chat."] = "Affiche dans le chat les buffs et procs que le suivi des buffs surveille pour votre spécialisation."
L["Prints what LazyGCore suggests right now, and why, to chat."] = "Affiche dans le chat ce que LazyGCore suggère en ce moment, et pourquoi."
L["Prints the details behind the DPS/HPS numbers to chat."] = "Affiche dans le chat le détail des chiffres DPS/HPS."
L["Resets every account-wide LazyGCore setting to its default after you confirm. Your saved profiles and this character's spec, talent build and custom rotations are kept."] = "Remet tous les réglages de compte de LazyGCore par défaut après confirmation. Vos profils sauvegardés ainsi que la spécialisation, le build de talents et les rotations personnalisées de ce personnage sont conservés."
L["Makes the action bar buttons holding this spell glow for 5 seconds, to check that LazyGCore finds it. Empty box: the current suggestion."] = "Fait briller pendant 5 secondes les boutons de barre d'action contenant ce sort, pour vérifier que LazyGCore le trouve. Champ vide : la suggestion actuelle."
L["Removes the test glow."] = "Retire la lueur de test."
L["Spell to test: type its name, or leave the box empty for the current suggestion. Enter or Test makes its action bar buttons glow."] = "Sort à tester : tapez son nom, ou laissez le champ vide pour la suggestion actuelle. Entrée ou Tester fait briller ses boutons de barre d'action."
L["Language of LazyGCore's text. Auto uses your game client's language. Applies after a UI reload."] = "Langue des textes de LazyGCore. Auto utilise la langue de votre client de jeu. S'applique après un rechargement de l'interface."
L["Reloads the interface now, so a new language takes effect."] = "Recharge l'interface maintenant, pour appliquer la nouvelle langue."
L["Sets every option on this page back to its default."] = "Remet toutes les options de cette page par défaut."
L["Switches between your custom rotation and LazyGCore's default priority for this spec."] = "Bascule entre votre rotation personnalisée et la priorité par défaut de LazyGCore pour cette spécialisation."
L["When the spell is suggested. Conditions marked * are estimates in combat, because Forever hides health, mana and most auras there."] = "Quand le sort est suggéré. Les conditions marquées * sont des estimations en combat, car Forever y masque la vie, le mana et la plupart des auras."
L["Adds the spell typed in the box to the end of your list, with the condition chosen beside it."] = "Ajoute le sort saisi dans le champ à la fin de votre liste, avec la condition choisie à côté."
L["Gives the entry selected in the list the spell, condition and values chosen here. A default rule becomes your own rule."] = "Applique à l'entrée sélectionnée dans la liste le sort, la condition et les valeurs choisis ici. Une règle par défaut devient votre propre règle."
L["Fills the list with LazyGCore's default priority for your current spec, so you can edit it."] = "Remplit la liste avec la priorité par défaut de LazyGCore pour votre spécialisation actuelle, pour que vous puissiez la modifier."
L["Saves the list as this spec's saved rotation."] = "Enregistre la liste comme rotation sauvegardée de cette spécialisation."
L["Loads this spec's saved rotation into the list."] = "Charge dans la liste la rotation sauvegardée de cette spécialisation."
L["No saved rotation for this spec yet: use Save Custom first."] = "Pas encore de rotation sauvegardée pour cette spécialisation : utilisez d'abord Sauvegarder."
L["Removes every spell from the list, after you confirm."] = "Retire tous les sorts de la liste, après confirmation."
L["Saves the list under the name typed in the box, so you can keep several rotations."] = "Enregistre la liste sous le nom saisi dans le champ, pour garder plusieurs rotations."
L["Your named rotations, with their spec and number of spells. Pick one, then Load or Delete it."] = "Vos rotations nommées, avec leur spécialisation et leur nombre de sorts. Choisissez-en une, puis Charger ou Supprimer."
L["Loads the named rotation picked beside it into the list."] = "Charge dans la liste la rotation nommée choisie à côté."
L["Deletes the named rotation picked beside it, after you confirm."] = "Supprime la rotation nommée choisie à côté, après confirmation."
L["Gives the named rotation picked below the name typed in the box."] = "Donne à la rotation nommée choisie ci-dessous le nom saisi dans le champ."
L["LazyGCore suggests from your list above instead of its default priority for this spec. Defensives and the cooldown slot still work as usual."] = "LazyGCore suggère depuis votre liste ci-dessus au lieu de sa priorité par défaut pour cette spécialisation. Les défensifs et l'emplacement de recharge fonctionnent comme d'habitude."
L["When nothing in your list is ready, the default priority fills in. Only applies when Use Custom Rotation is on."] = "Quand rien dans votre liste n'est prêt, la priorité par défaut prend le relais. Seulement si l'option Utiliser la rotation personnalisée est activée."
L["Never suggest the spell typed in the box (also not in the cooldown slot or the cooldown glow)."] = "Ne jamais suggérer le sort saisi dans le champ (ni dans l'emplacement de recharge, ni dans la lueur de recharge)."
L["Lets the spell in the box, or the one selected in the list, be suggested again."] = "Permet au sort du champ, ou à celui sélectionné dans la liste, d'être de nouveau suggéré."
L["Prints every excluded spell to chat."] = "Affiche dans le chat tous les sorts exclus."
L["Removes every exclusion, after you confirm."] = "Retire toutes les exclusions, après confirmation."
L["Turns LazyGCore off while you are in a battleground: no display, suggestions or glows there."] = "Désactive LazyGCore en champ de bataille : ni affichage, ni suggestions, ni lueurs."
L["Turns LazyGCore off while you are in an arena: no display, suggestions or glows there."] = "Désactive LazyGCore en arène : ni affichage, ni suggestions, ni lueurs."
L["Stops spell suggestions everywhere, not only in battlegrounds or arenas, but keeps the display with the DPS strip and swing timer."] = "Arrête les suggestions de sorts partout, pas seulement en champ de bataille ou en arène, mais garde l'affichage avec le bandeau DPS et le chrono de frappe."
L["Shows an estimated parse percentile in the Stats window, based on this spec's benchmark numbers."] = "Affiche une estimation du percentile de parse dans la fenêtre Stats, d'après les chiffres de référence de cette spécialisation."
L["Keeps your last fight's numbers on the DPS strip after combat ends instead of hiding it. Only applies when Show DPS/HPS is on."] = "Garde les chiffres de votre dernier combat sur le bandeau DPS après le combat au lieu de le masquer. Seulement si l'option Afficher DPS/HPS est activée."
L["Shows how your DPS compares to your personal best: the difference in DPS on the DPS strip, +/- % in the Stats window."] = "Montre l'écart entre votre DPS et votre record personnel : la différence de DPS sur le bandeau DPS, +/- % dans la fenêtre Stats."
L["Shows your rotation efficiency score on the DPS strip and in the Stats window."] = "Affiche votre score d'efficacité de rotation sur le bandeau DPS et dans la fenêtre Stats."
L["When the DPS numbers start over. Each combat: every fight. Boss only: fights add up until a boss fight starts. Manual: only when you press Reset Now."] = "Quand les chiffres DPS repartent de zéro. Chaque combat : à chaque combat. Boss uniquement : les combats s'additionnent jusqu'au début d'un combat de boss. Manuel : seulement quand vous appuyez sur Réinitialiser."
L["Clears the DPS numbers now (in Manual mode also Blizzard's damage meter)."] = "Efface les chiffres DPS maintenant (en mode Manuel, aussi le compteur de dégâts de Blizzard)."
L["Prints your last 10 fights to chat."] = "Affiche vos 10 derniers combats dans le chat."
L["Dark box behind the DPS strip. 0 (default) = no box. Only applies when Show DPS/HPS is on."] = "Fond sombre derrière le bandeau DPS. 0 (par défaut) = aucun fond. Seulement si l'option Afficher DPS/HPS est activée."
L["Opacity of the floating Stats window."] = "Opacité de la fenêtre flottante Stats."
L["Adds a player's gear score and item level to their tooltip when you hover them."] = "Ajoute le GearScore et le niveau d'objet d'un joueur à son infobulle quand vous le survolez."
L["Rescans your gear and buffs and updates the boxes above."] = "Réanalyse votre équipement et vos buffs et met à jour les cases ci-dessus."
L["Saves your current settings as a profile with the name typed in the box (replaces a profile of that name) and makes it active."] = "Enregistre vos réglages actuels en profil sous le nom saisi dans le champ (remplace un profil du même nom) et l'active."
L["Loads the profile selected in the list. Double-clicking a profile does the same."] = "Charge le profil sélectionné dans la liste. Un double-clic sur un profil fait de même."
L["Deletes the selected profile, after you confirm. The Default profile can't be deleted."] = "Supprime le profil sélectionné, après confirmation. Le profil Défaut ne peut pas être supprimé."
L["Gives the selected profile the name typed in the box."] = "Donne au profil sélectionné le nom saisi dans le champ."
L["Copies the selected profile (or the active one) to a new profile with the name typed in the box."] = "Copie le profil sélectionné (ou l'actif) vers un nouveau profil portant le nom saisi dans le champ."
L["When your detected spec changes, loads the profile you assigned to that spec with Use for this spec."] = "Quand votre spécialisation détectée change, charge le profil attribué à cette spécialisation avec Utiliser pour cette spécialisation."
L["Assigns the selected profile (or the active one) to your current spec."] = "Attribue le profil sélectionné (ou l'actif) à votre spécialisation actuelle."
L["Removes the profile assigned to your current spec."] = "Retire le profil attribué à votre spécialisation actuelle."
L["Puts the selected profile (or the active one) in the box as a text string you can copy and share. The active profile exports your current settings, including changes you have not saved."] = "Place le profil sélectionné (ou l'actif) dans le champ sous forme de chaîne de texte à copier et partager. Le profil actif exporte vos réglages actuels, y compris les modifications non sauvegardées."
L["Saves the profile string pasted in the box as a profile, named by the name box or by the string itself."] = "Enregistre comme profil la chaîne collée dans le champ, nommé d'après le champ de nom ou d'après la chaîne elle-même."
L["While the talent frame is open, a green NEXT glow marks the next talent of your build, and the right spec tab and the Apply button are pointed out. Also prints a chat note when a point is free."] = "Quand la fenêtre des talents est ouverte, une lueur verte SUIV marque le prochain talent de votre build, et le bon onglet de spécialisation et le bouton Appliquer sont signalés. Affiche aussi une note dans le chat quand un point est libre."
L["Makes the talent button on the micro menu glow while you have an unspent point for your build. Only applies when Glow the next talent in the talent frame is on."] = "Fait briller le bouton des talents du micro-menu tant qu'il vous reste un point à dépenser pour votre build. Seulement si l'option Faire briller le prochain talent dans la fenêtre des talents est activée."
L["Opens the Next Talent popup with the next talent of your build."] = "Ouvre la fenêtre Talent suivant avec le prochain talent de votre build."
L["Opens the build browser to pick another talent build for your spec."] = "Ouvre le navigateur de builds pour choisir un autre build de talents pour votre spécialisation."
L["Shows this spec's recommended talent build below."] = "Affiche ci-dessous le build de talents recommandé de cette spécialisation."
L["Picks this spec's leveling build."] = "Choisit le build de montée en niveau de cette spécialisation."
L["Picks this spec's PvE build (dungeons and raids)."] = "Choisit le build JcE de cette spécialisation (donjons et raids)."
L["Picks this spec's PvP build."] = "Choisit le build JcJ de cette spécialisation."
L["Cycles this spec's build type: Leveling, PvE, PvP."] = "Fait défiler le type de build de cette spécialisation : montée en niveau, JcE, JcJ."
L["Picks which of this spec's talent builds the guide shows and follows."] = "Choisit le build de talents de cette spécialisation que le guide affiche et suit."
L["Re-reads your talents and stops following a build started with Start Build."] = "Relit vos talents et arrête de suivre un build lancé avec Commencer le build."
L["Opens the game's talent frame."] = "Ouvre la fenêtre des talents du jeu."
L["Opens the game's macro window (/macro), where you drag the macros you created to your bars."] = "Ouvre la fenêtre des macros du jeu (/macro), d'où vous glissez les macros créées sur vos barres."
L["Updates every macro you already created from this page to its latest version."] = "Met à jour vers leur dernière version toutes les macros déjà créées depuis cette page."
L["Visibility"] = "Visibilité"
L["Suggestions"] = "Suggestions"
L["Troubleshooting"] = "Dépannage"
L["Hide name, reason and DPS strip"] = "Masquer nom, raison et bandeau DPS"
L["Buff reminder text"] = "Texte de rappel de buff"
L["List all missing buffs"] = "Lister tous les buffs manquants"
L["Suggest buffs & pets"] = "Suggérer buffs et familiers"
L["Glow the suggested spell"] = "Faire briller le sort suggéré"
L["Saved rotations"] = "Rotations sauvegardées"
L["Balance: remind you to be in Moonkin Form out of combat, and suggest shifting back into it after a caster-form heal in combat"] = "Équilibre : vous rappelle d'être en Forme de sélénien hors combat, et suggère d'y revenir après un soin lancé en forme normale en combat"
L["Feral, in groups only (solo, LazyGCore picks the form itself). Bear always suggests Bear Form, Cat never does. Auto: Bear when you are in Bear Form, the group made you its tank, you run a Bear build or your last shift was into Bear; otherwise Cat"] = "Farouche, en groupe uniquement (en solo, LazyGCore choisit la forme lui-même). Ours suggère toujours Forme d'ours, Félin jamais. Auto : Ours si vous êtes en Forme d'ours, si le groupe vous a désigné tank, si vous jouez un build Ours ou si votre dernière transformation était en ours ; sinon Félin"
L["In Bear Form, in combat, suggest Frenzied Regeneration below this health %. Needs Suggest defensives on (Combat page)"] = "En Forme d'ours, en combat, suggère Régénération frénétique sous ce % de vie. Nécessite Suggérer les défensifs activé (page Combat)"
L["Suggest Hunter's Mark on elites, group targets, players and mobs above 60% health. Survival skips normal solo mobs it is about to melee, unless it has Expose Prey (which only procs on Marked targets)"] = "Suggère Marque du chasseur sur les élites, les cibles de groupe, les joueurs et les monstres au-dessus de 60 % de vie. Survie l'ignore sur les monstres normaux en solo qu'il va affronter en mêlée, sauf avec Exposition de proie (qui ne se déclenche que sur les cibles marquées)"
L["Out of combat, remind you to call your pet, revive it if it died, or feed it when it is not happy. Skipped if you have the Lone Wolf talent"] = "Hors combat, vous rappelle d'appeler votre familier, de le ranimer s'il est mort ou de le nourrir s'il n'est pas heureux. Ignoré si vous avez le talent Loup solitaire"
L["Out of combat, remind you to put up your combat aspect: Aspect of the Hawk (Monkey before level 10); Survival uses Monkey until it learns Aspect of the Beast. Waits while Cheetah, Pack or Wild is on, and in combat warns when Cheetah or Pack is still on"] = "Hors combat, vous rappelle d'activer votre aspect de combat : Aspect du faucon (Aspect du singe avant le niveau 10) ; Survie utilise le singe jusqu'à apprendre Aspect de la bête. Attend tant que Guépard, Meute ou Nature est actif, et avertit en combat si Guépard ou Meute est encore actif"
L["In combat, suggest Mend Pet when your pet drops below this % (out of combat it reminds you below 60%). Forever hides pet health in combat: LazyGCore estimates it from the damage and heals your pet takes. Needs Suggest defensives on (Combat page)"] = "En combat, suggère Guérison du familier quand votre familier passe sous ce % (hors combat, rappel sous 60 %). Forever masque la vie du familier en combat : LazyGCore l'estime d'après les dégâts et soins qu'il reçoit. Nécessite Suggérer les défensifs activé (page Combat)"
L["Arcane: Arcane Blast stacks to build on elites, bosses, groups and players before Arcane Wrath and Arcane Missiles. Each stack adds 15% of your Intellect as spell damage for 15 seconds from the first Blast, but makes the next Blast cost more (trash always gets one Blast)"] = "Arcanes : cumuls de Déflagration des arcanes à accumuler sur les élites, boss, groupes et joueurs avant Courroux des arcanes et Projectiles des arcanes. Chaque cumul ajoute 15 % de votre Intelligence aux dégâts des sorts pendant 15 secondes à partir de la première Déflagration, mais renchérit la suivante (les monstres mineurs reçoivent toujours une Déflagration)"
L["Fire with 3 points in Improved Scorch: keep this many Fire Vulnerability stacks up with Scorch on bosses, skull-marked targets and elites (solo or in a raid; never on players)"] = "Feu avec 3 points dans Brûlure améliorée : maintient ce nombre de cumuls de Vulnérabilité au Feu avec Brûlure sur les boss, les cibles marquées d'un crâne et les élites (en solo ou en raid ; jamais sur les joueurs)"
L["Suggest Evocation when you run low on mana: out of combat below the Evocation Threshold, in combat once you can't afford your filler spell"] = "Suggère Évocation quand vous manquez de mana : hors combat sous le Seuil d'Évocation, en combat dès que vous ne pouvez plus payer votre sort de remplissage"
L["In combat, suggest a mana gem when you run low on mana, before Evocation (needs Suggest defensives and Suggest cooldowns on, Combat page). Out of combat, remind you to conjure one when your bags have none"] = "En combat, suggère une gemme de mana quand vous manquez de mana, avant Évocation (nécessite Suggérer les défensifs et Suggérer les temps de recharge activés, page Combat). Hors combat, vous rappelle d'en invoquer une si vos sacs n'en contiennent aucune"
L["Suggest Evocation when mana is below this %. Out of combat only: Forever hides your mana in combat, so there Evocation is suggested once you can't afford your filler spell"] = "Suggère Évocation quand le mana est sous ce %. Hors combat uniquement : Forever masque votre mana en combat, Évocation y est donc suggérée dès que vous ne pouvez plus payer votre sort de remplissage"
L["Suggest Consecration in melee range when mana allows, mostly on packs and elites. Applies to every spec (Holy only when solo)"] = "Suggère Consécration en mêlée quand le mana le permet, surtout sur les groupes de monstres et les élites. S'applique à toutes les spécialisations (Sacré uniquement en solo)"
L["Protection: on keeps Holy Shield up whenever you are in melee. Off: only against elites or when your health is below 50%"] = "Protection : activé, maintient Bouclier sacré dès que vous êtes en mêlée. Désactivé : seulement contre les élites ou quand votre vie est sous 50 %"
L["Out of combat, remind you to put your blessing on yourself when it is missing or has under 1 minute left. Holy in a group: also Blessing of Kings on the ally you heal"] = "Hors combat, vous rappelle de vous appliquer votre bénédiction quand elle manque ou qu'il lui reste moins d'1 minute. Sacré en groupe : aussi Bénédiction des rois sur l'allié que vous soignez"
L["The blessing the reminder keeps on you (needs Blessing Reminder on). Auto: Wisdom for Holy, Kings for Protection, Might otherwise. Might is used until the chosen one is learned"] = "La bénédiction que le rappel maintient sur vous (nécessite Rappel de bénédiction activé). Auto : Sagesse pour Sacré, Rois pour Protection, Puissance sinon. Puissance est utilisée tant que celle choisie n'est pas apprise"
L["Auto: the new Shadow Word: Pain lands right as the old one ends (recasting early throws away its remaining ticks). Or refresh when this many seconds remain. Applies to every spec while it deals damage"] = "Auto : la nouvelle Mot de l'ombre : Douleur arrive juste quand l'ancienne se termine (relancer trop tôt perd ses ticks restants). Ou le rafraîchir quand il reste ce nombre de secondes. S'applique à toutes les spécialisations quand vous infligez des dégâts"
L["Only suggest Shadow Word: Death while your own health is above this % (it hurts you if the target survives)"] = "Ne suggère Mot de l'ombre : Mort que si votre propre vie est au-dessus de ce % (il vous blesse si la cible survit)"
L["Never suggest Fade. When off, Fade is suggested in a group as soon as you pull threat"] = "Ne jamais suggérer Oubli. Désactivé, Oubli est suggéré en groupe dès que vous prenez la menace"
L["In combat, suggest Mind Blast every time it comes off cooldown. Off: the normal priority decides, and normal mobs often get your wand to save mana"] = "En combat, suggère Attaque mentale à chaque fin de recharge. Désactivé : la priorité normale décide, et les monstres normaux reçoivent souvent votre baguette pour économiser le mana"
L["Combo points to build before Eviscerate. Auto: 5 with talents (4 before), and 4 on normal mobs while questing (3 below level 20) so they die sooner. A target about to die gets Eviscerate from 2 points"] = "Points de combo à accumuler avant Éviscération. Auto : 5 avec talents (4 avant), et 4 sur les monstres normaux en quête (3 sous le niveau 20) pour qu'ils meurent plus vite. Une cible sur le point de mourir reçoit Éviscération dès 2 points"
L["Keep Slice and Dice up (from 2 combo points, 4 for Combat) on targets above 25% health. Leveling and Combat skip normal mobs while questing; Assassination and Subtlety skip players. Off: never suggest it"] = "Maintient Débiter (dès 2 points de combo, 4 en Combat) sur les cibles au-dessus de 25 % de vie. Montée en niveau et Combat ignorent les monstres normaux en quête ; Assassinat et Finesse ignorent les joueurs. Désactivé : ne jamais le suggérer"
L["Auto: each spec's own choice (Assassination: Rupture on elites, Subtlety: on elites, groups and players, Combat and leveling: Eviscerate only). Rupture: Rupture first whenever it is missing on a target above 35% health. Eviscerate: never Rupture"] = "Auto : le choix propre à chaque spécialisation (Assassinat : Rupture sur les élites, Finesse : sur les élites, groupes et joueurs, Combat et montée en niveau : Éviscération uniquement). Rupture : Rupture en priorité dès qu'elle manque sur une cible au-dessus de 35 % de vie. Éviscération : jamais Rupture"
L["Assassination and Combat: in a group, suggest Vanish against an elite (while you don't hold threat) so you can use a stealth opener again. Subtlety has its own Vanish rule"] = "Assassinat et Combat : en groupe, suggère Disparition contre un élite (quand vous n'avez pas la menace) pour réutiliser une ouverture furtive. Finesse a sa propre règle pour Disparition"
L["Suggest your damage and buff totems (Searing, Magma, Strength of Earth, water totems, totem sets), mostly on elites, groups and players; Magma Totem on packs. Off: only utility totems such as Stoneclaw, Grounding, Tremor and Mana Tide are still suggested"] = "Suggère vos totems de dégâts et de buff (Incendiaire, Magma, Force de la Terre, totems d'eau, ensembles de totems), surtout sur les élites, groupes et joueurs ; Totem de Magma sur les groupes de monstres. Désactivé : seuls les totems utilitaires comme Griffes de pierre, Glèbe, Séisme et Vague de mana sont encore suggérés"
L["Enhancement and Restoration, once you have Water Shield: remind you to refresh it out of combat when under 1 minute, and recast it in combat when it drops"] = "Amélioration et Restauration, une fois Bouclier d'eau appris : vous rappelle de le rafraîchir hors combat sous 1 minute, et de le relancer en combat quand il disparaît"
L["Restoration: suggest Chain Heal when at least this many group members are below 80% health. In combat Forever hides group health: LazyGCore estimates it from the damage and heals they take"] = "Restauration : suggère Salve de guérison quand au moins ce nombre de membres du groupe sont sous 80 % de vie. En combat, Forever masque la vie du groupe : LazyGCore l'estime d'après les dégâts et soins qu'ils reçoivent"
L["Suggest Life Tap when you run low on mana and your health is above 50%. Between pulls it also reminds you below 60% mana when your health is above 75%"] = "Suggère Connexion quand vous manquez de mana et que votre vie est au-dessus de 50 %. Entre les pulls, vous le rappelle aussi sous 60 % de mana si votre vie est au-dessus de 75 %"
L["Suggest Life Tap when mana is below this % (health above 50%). Forever hides your mana in combat, so there Life Tap is suggested once you can't afford Shadow Bolt. Between pulls a separate reminder appears below 60% mana"] = "Suggère Connexion quand le mana est sous ce % (vie au-dessus de 50 %). Forever masque votre mana en combat, Connexion y est donc suggérée dès que vous ne pouvez plus payer Trait de l'ombre. Entre les pulls, un rappel séparé apparaît sous 60 % de mana"
L["Solo, in combat: suggest Health Funnel when your demon drops below this % and your own health is above 55%. Forever hides pet health in combat: LazyGCore estimates it from the damage and heals your demon takes. Needs Suggest defensives on (Combat page)"] = "En solo, en combat : suggère Captation de vie quand votre démon passe sous ce % et que votre propre vie est au-dessus de 55 %. Forever masque la vie du familier en combat : LazyGCore l'estime d'après les dégâts et soins que votre démon reçoit. Nécessite Suggérer les défensifs activé (page Combat)"
L["Your one Curse per target. Auto: Curse of the Elements on elites and in groups (Curse of Weakness on elites before you learn it); on players Curse of Tongues for casters, Curse of Exhaustion or Weakness for the rest. A fixed curse goes on elites, group targets and players; None leaves the Curse to another Warlock (Banes still apply)"] = "Votre unique malédiction par cible. Auto : Malédiction des éléments sur les élites et en groupe (Malédiction de faiblesse sur les élites avant de l'apprendre) ; sur les joueurs, Malédiction des langages pour les lanceurs de sorts, Malédiction de fatigue ou de faiblesse pour les autres. Une malédiction fixe va sur les élites, cibles de groupe et joueurs ; Aucune laisse la malédiction à un autre démoniste (les Plaies s'appliquent toujours)"
L["Destruction only. Also picks your weapon stone (Firestone with Incinerate, Spellstone with Shadow Bolt) and the demon you sacrifice (Sayaad or Imp). Auto: Incinerate if you have the Incinerate talent and 5 points in Shadow and Flame, otherwise Shadow Bolt"] = "Destruction uniquement. Choisit aussi votre pierre d'arme (Pierre de feu avec Incinérer, Pierre de sort avec Trait de l'ombre) et le démon que vous sacrifiez (Sayaad ou diablotin). Auto : Incinérer si vous avez le talent Incinérer et 5 points dans Ombre et flammes, sinon Trait de l'ombre"
L["Protection: build Sunder Armor to this many stacks on elites and in dungeons and raids, and refresh it before it drops (normal mobs while questing get 2)"] = "Protection : accumule Fracasser armure jusqu'à ce nombre de cumuls sur les élites et en donjon et raid, et le rafraîchit avant qu'il expire (les monstres normaux en quête en reçoivent 2)"
L["Use Heroic Strike when rage is above this (Auto = per spec: 30 leveling, 60 Arms/Fury, 45 Protection). In combat Rage is hidden: LazyGCore checks you could still afford a spell of that cost (30+: Mortal Strike / Bloodthirst, 25: Intimidating Shout / Whirlwind, 20: Cleave / Thunder Clap, 15 or less: Heroic Strike)"] = "Utilise Frappe héroïque quand la rage dépasse cette valeur (Auto = selon la spécialisation : 30 montée en niveau, 60 Armes/Fureur, 45 Protection). En combat la rage est masquée : LazyGCore vérifie que vous pourriez encore payer un sort de ce coût (30+ : Frappe mortelle / Sanguinaire, 25 : Cri d'intimidation / Tourbillon, 20 : Enchaînement / Coup de tonnerre, 15 ou moins : Frappe héroïque)"
L["Protection: on suggests Shield Block whenever you are tanking in melee. Off: only against elites or when your health is below 50%"] = "Protection : activé, suggère Maîtrise du blocage dès que vous tankez en mêlée. Désactivé : seulement contre les élites ou quand votre vie est sous 50 %"
L["Suggest Battle Shout whenever it is missing (out of combat also when under 10 seconds remain)"] = "Suggère Cri de guerre dès qu'il manque (hors combat aussi quand il reste moins de 10 secondes)"

-- sim pass: raid-only utility options
L["Faerie Fire in raids"] = "Lucioles en raid"
L["Balance: keep Faerie Fire's armor debuff on the boss in raids. It only helps physical attackers and costs you a GCD and mana, so leave it off unless your raid has no other armor debuff. Groups of 5 always get it"] = "Équilibre : maintient le débuff d'armure de Lucioles sur le boss en raid. Il n'aide que les attaquants physiques et vous coûte un temps de recharge global et du mana : laissez-le désactivé sauf si votre raid n'a pas d'autre débuff d'armure. En groupe de 5, il est toujours suggéré"
L["Vampiric Embrace in raids"] = "Étreinte vampirique en raid"
L["Shadow: keep Vampiric Embrace on the boss in raids so your Shadow damage heals your party. It does no damage and costs a GCD every 30 seconds. In groups of 5 and in battlegrounds it is always suggested; solo only while your health is below 60%"] = "Ombre : maintient Étreinte vampirique sur le boss en raid pour que vos dégâts d'Ombre soignent votre groupe. Elle n'inflige aucun dégât et coûte un temps de recharge global toutes les 30 secondes. En groupe de 5 et en champ de bataille, elle est toujours suggérée ; en solo, seulement tant que votre vie est sous 60 %"
L["Shows the colored ring around the main icon. The ring is also the swing timer, so hiding it also hides that swing timer (the swing timer bars stay visible)."] = "Affiche l'anneau coloré autour de l'icône principale. L'anneau sert aussi de chrono de frappe : le masquer masque aussi ce chrono (les barres du chrono de frappe restent visibles)."
L["Hide/show the spell name, reason and DPS strip (and the queue in the stacked layout)"] = "Masquer/afficher le nom du sort, la raison et le bandeau DPS (et la file dans la disposition empilée)"

