-- fix_talentrange: gear score label (GS) and auto attack reasons
L["Show your gear score (GS) under the keybind on the rotation icon. GS rates your equipped gear by item level and quality; the colour is its tier (green, blue, purple). Only shown at level 60."] = "Affiche votre GearScore (GS) sous le raccourci sur l'icône de rotation. Le GS évalue votre équipement porté selon le niveau d'objet et la qualité ; la couleur indique son palier (vert, bleu, violet). Affiché uniquement au niveau 60."
L["GS"] = "GS"
L["No wand and nothing to cast: melee."] = "Pas de baguette et rien à lancer : mêlée."
L["Start auto attack while energy builds."] = "Lancez l'attaque automatique pendant que l'énergie remonte."
L["Closing in - start swinging when it reaches you."] = "Rapprochement : frappez dès qu'il vous atteint."

-- fix_macros: per-character class macros, Account section, move to character
L["Account (all characters)"] = "Compte (tous les personnages)"
L["Will be saved to General (account) macros"] = "Sera enregistrée dans les macros générales (compte)"
L["Will be saved to Character macros"] = "Sera enregistrée dans les macros du personnage"
L["All your characters see this copy. Move it to keep it on this character only."] = "Tous vos personnages voient cette copie. Déplacez-la pour la garder sur ce personnage uniquement."
L["Move to this character"] = "Déplacer vers ce personnage"
L["Moves this macro from the General (account) macros to this character's macros. Other characters lose this macro; put it back on your action bar."] = "Déplace cette macro des macros générales (compte) vers les macros de ce personnage. Les autres personnages perdent cette macro ; remettez-la sur votre barre d'action."
L["(account macro)"] = "(macro de compte)"
L["%s moved to this character's macros. Put it back on your action bar."] = "%s a été déplacée vers les macros de ce personnage. Remettez-la sur votre barre d'action."
L["Could not move %s; nothing was deleted."] = "Impossible de déplacer %s ; rien n'a été supprimé."
L["Your General (account) macros are full (%d). Delete one in the macro window (/macro) first."] = "Vos macros générales (compte) sont pleines (%d). Supprimez-en d'abord une dans la fenêtre des macros (/macro)."
L["Your character macros are full (%d). Delete one in the macro window (/macro) first."] = "Vos macros du personnage sont pleines (%d). Supprimez-en d'abord une dans la fenêtre des macros (/macro)."
L["Use your top trinket (slot 13)"] = "Utiliser votre bijou du haut (emplacement 13)"
L["Use your bottom trinket (slot 14)"] = "Utiliser votre bijou du bas (emplacement 14)"
L["Focus your mouseover, else your target"] = "Focaliser le survol, sinon votre cible"
L["Clear your focus"] = "Effacer votre focalisation"
L["Target what your focus is targeting"] = "Cibler la cible de votre focalisation"
L["Put a Skull on your target (press again to remove it)"] = "Placer une tête de mort sur votre cible (appuyez à nouveau pour la retirer)"
L["Start a ready check (group leader or raid assistant)"] = "Lancer un appel (chef de groupe ou assistant de raid)"
L["Show or hide the LazyGCore rotation display"] = "Afficher ou masquer l'affichage de rotation de LazyGCore"
L["Reload the user interface"] = "Recharger l'interface"


-- Growth features (Group Sync, share build, welcome tour, version notice)
L["A newer LazyGCore is out (%s) - update on CurseForge."] = "Une version plus récente de LazyGCore est disponible (%s) - mettez-la à jour sur CurseForge."
L["Group Sync is off (Combat settings)."] = "La synchro de groupe est désactivée (paramètres Combat)."
L["You are not in a group."] = "Vous n'êtes pas dans un groupe."
L["No other LazyGCore users in your group yet."] = "Aucun autre utilisateur de LazyGCore dans votre groupe pour l'instant."
L["LazyGCore users in your group"] = "Utilisateurs de LazyGCore dans votre groupe"
L["newer"] = "plus récente"
L["List the LazyGCore users in your group and their versions"] = "Lister les utilisateurs de LazyGCore de votre groupe et leurs versions"
L["Group Sync"] = "Synchro de groupe"
L["LazyGCore users in your party or raid quietly share their addon version, interrupt and big cooldowns over the hidden addon channel: the KICK! box shows who kicks next, and group cooldowns show under the display. Nothing is posted to chat and players without LazyGCore see nothing. Never sent while the game restricts addon messages (boss encounters, PvP)."] = "Les utilisateurs de LazyGCore de votre groupe ou raid partagent discrètement, via le canal caché des addons, leur version de l'addon, leur interruption et leurs gros temps de recharge : la case KICK ! indique qui interrompt ensuite, et les temps de recharge du groupe s'affichent sous l'affichage. Rien n'est publié dans la discussion et les joueurs sans LazyGCore ne voient rien. Jamais envoyé quand le jeu restreint les messages d'addon (rencontres de boss, JcJ)."
L["Show group cooldowns"] = "Afficher les temps de recharge du groupe"
L["Shows a small line under the display when a LazyGCore user in your group uses a big defensive or raid cooldown (Shield Wall, Divine Shield, Innervate, Mana Tide Totem...). Hidden when you are solo. Only applies when Group Sync is on."] = "Affiche une petite ligne sous l'affichage quand un utilisateur de LazyGCore de votre groupe utilise un gros temps de recharge défensif ou de raid (Mur protecteur, Bouclier divin, Innervation, Totem de Vague de mana...). Masquée en solo. S'applique seulement si la synchro de groupe est activée."
L["New version notice"] = "Avis de nouvelle version"
L["Prints one line in your own chat window, once per session, when a group member runs a newer LazyGCore. Nobody else sees it."] = "Affiche une ligne dans votre propre fenêtre de discussion, une fois par session, quand un membre du groupe utilise une version plus récente de LazyGCore. Personne d'autre ne la voit."
L["You kick next"] = "À vous d'interrompre"
L["%s kicks next"] = "À %s d'interrompre"
L["The welcome tour opens after combat."] = "La visite de bienvenue s'ouvrira après le combat."
L["Replay the short welcome tour"] = "Rejouer la courte visite de bienvenue"
L["Welcome"] = "Bienvenue"
L["Your rotation display"] = "Votre affichage de rotation"
L["/lazygcore"] = "/lazygcore"
L["This is LazyGCore's display: the big icon is the ability to use next, PREV shows your last casts and NEXT what comes after. A grey icon is out of range or short on mana, the small icon beside it is a cooldown ready to use, and the LazyGCore logo means nothing to press. It shows in combat and when you target an enemy. Drag it to move it."] = "Voici l'affichage de LazyGCore : la grande icône est la technique à utiliser ensuite, PRÉC montre vos derniers sorts et SUIV ce qui vient après. Une icône grise est hors de portée ou manque de mana, la petite icône à côté est un temps de recharge prêt à l'emploi, et le logo LazyGCore signifie qu'il n'y a rien à appuyer. Il apparaît en combat et quand vous ciblez un ennemi. Faites-le glisser pour le déplacer."
L["The Talents page shows the next talent of your build and lets you pick another build. While the talent frame is open, your next talent glows."] = "La page Talents montre le prochain talent de votre build et permet d'en choisir un autre. Tant que la fenêtre des talents est ouverte, votre prochain talent brille."
L["Skip tour"] = "Passer la visite"
L["Next"] = "Suivant"
L["Goes to the next step of the tour."] = "Passe à l'étape suivante de la visite."
L["Done"] = "Terminé"
L["Step %d of %d"] = "Étape %d sur %d"
L["Enjoying LazyGCore? A rating on CurseForge helps other players find it."] = "Vous aimez LazyGCore ? Une note sur CurseForge aide d'autres joueurs à le trouver."
L["Click the link, then press Ctrl+C to copy it."] = "Cliquez sur le lien, puis appuyez sur Ctrl+C pour le copier."
L["CurseForge"] = "CurseForge"
L["Say"] = "Dire"
L["Party"] = "Groupe"
L["Raid"] = "Groupe de raid"
L["Guild"] = "Guilde"
L["Whisper target"] = "Chuchoter à la cible"
L["Whisper"] = "Chuchoter à"
L["no player targeted"] = "aucun joueur ciblé"
L["leveling build"] = "build de montée en niveau"
L["PvE build"] = "build JcE"
L["PvP build"] = "build JcJ"
L["You are not in a raid."] = "Vous n'êtes pas dans un raid."
L["You are not in a guild."] = "Vous n'êtes pas dans une guilde."
L["Target a player to whisper your build."] = "Ciblez un joueur pour lui chuchoter votre build."
L["Chat is restricted right now. Try again after the fight."] = "La discussion est restreinte pour le moment. Réessayez après le combat."
L["Wait a few seconds before sharing again."] = "Attendez quelques secondes avant de partager à nouveau."
L["Could not post the build."] = "Impossible de publier le build."
L["No talent build to share for this spec."] = "Aucun build de talents à partager pour cette spécialisation."
L["Posts to: %s"] = "Publié dans : %s"
L["Share build"] = "Partager le build"
L["Post to"] = "Publier dans"
L["Where Share build posts your build: Say, Party, Raid, Guild, or a whisper to the player you target."] = "Où Partager le build publie votre build : Dire, Groupe, Groupe de raid, Guilde ou un chuchotement au joueur ciblé."

