-- Share LazyGCore tab, chat channels, contact links, welcome tour (UI/ShareLazyGCore, UI/Welcome)
L["Other LazyGCore users: %d in your group, %d in your guild"] = "Autres utilisateurs de LazyGCore : %d dans votre groupe, %d dans votre guilde"
L["Turn on Share gear score with LazyGCore users (Parsing tab) to see how many players around you use LazyGCore."] = "Activez Partager le GearScore avec les utilisateurs de LazyGCore (onglet Parsing) pour voir combien de joueurs autour de vous utilisent LazyGCore."
L["Follow LazyGCore"] = "Suivre LazyGCore"
L["Enjoying LazyGCore? Follow it and add it to your favorites on CurseForge: you hear about every update first, and it helps other players find it."] = "Vous aimez LazyGCore ? Suivez-le et ajoutez-le à vos favoris sur CurseForge : vous êtes informé en premier de chaque mise à jour, et cela aide d'autres joueurs à le trouver."
L["Share LazyGCore"] = "Partager LazyGCore"
L["Know someone who would like LazyGCore? Share it in one click. When your group runs LazyGCore together, Group Sync shows who kicks next."] = "Vous connaissez quelqu'un qui aimerait LazyGCore ? Partagez-le en un clic. Quand votre groupe utilise LazyGCore, la synchro de groupe indique qui interrompt ensuite."
L["I use LazyGCore Forever for my rotation and talents: it shows what to press next. Free on CurseForge: %s - get it too and Group Sync shows who kicks next!"] = "J'utilise LazyGCore Forever pour ma rotation et mes talents : il montre quoi lancer ensuite. Gratuit sur CurseForge : %s - prends-le aussi et la synchro de groupe montre qui interrompt !"
L["Posts ONE chat line telling your friends about LazyGCore Forever, with the CurseForge link, to the channel picked in Post to. Sent only when you click, never automatically."] = "Publie UNE ligne de chat qui présente LazyGCore Forever à vos amis, avec le lien CurseForge, dans le canal choisi dans Publier dans. Envoyé uniquement quand vous cliquez, jamais automatiquement."
L["Where Share LazyGCore and Share build post: Say, Party, Raid, Guild, a whisper to the player you target, or a chat channel you have joined (Trade, General, LookingForGroup ...). Public channels: one share a minute."] = "Où Partager LazyGCore et Partager le build publient : Dire, Groupe, Groupe de raid, Guilde, un chuchotement au joueur ciblé ou un canal de discussion rejoint (Commerce, Général, RechercheDeGroupe ...). Canaux publics : une fois par minute."
L["Target a player to whisper the link."] = "Ciblez un joueur pour lui chuchoter le lien."
L["Could not post the message."] = "Impossible de publier le message."
L["Usage: /lazygcore share [say / party / raid / guild / whisper / trade / general / channel number]"] = "Utilisation : /lazygcore share [say / party / raid / guild / whisper / trade / general / numéro de canal]"
L["Tell your friends about LazyGCore: posts one chat line (say, party, raid, guild, whisper or a chat channel such as trade)"] = "Parlez de LazyGCore à vos amis : publie une ligne de chat (dire, groupe, raid, guilde, chuchotement ou un canal comme Commerce)"
L["You can also type /lazygcore share, or /lazygcore share trade, general, guild, party ..."] = "Vous pouvez aussi taper /lazygcore share, ou /lazygcore share trade, general, guild, party ..."
L["Suggestions & bug reports"] = "Suggestions et signalements de bugs"
L["Have an idea, or did LazyGCore suggest something wrong? Tell me on CurseForge: leave a comment on the LazyGCore page or message me on my profile. Include your class, spec and what /lazygcore status prints."] = "Une idée, ou LazyGCore a suggéré quelque chose de faux ? Dites-le-moi sur CurseForge : laissez un commentaire sur la page de LazyGCore ou écrivez-moi via mon profil. Indiquez votre classe, votre spécialisation et ce qu'affiche /lazygcore status."
L["Comments"] = "Commentaires"
L["Comments on the LazyGCore Forever page. Click the link, then press Ctrl+C to copy it."] = "Commentaires sur la page de LazyGCore Forever. Cliquez sur le lien, puis appuyez sur Ctrl+C pour le copier."
L["The author's CurseForge profile. Click the link, then press Ctrl+C to copy it."] = "Le profil CurseForge de l'auteur. Cliquez sur le lien, puis appuyez sur Ctrl+C pour le copier."
L["Welcome tour"] = "Visite de bienvenue"
L["A short tour of the display and every settings tab."] = "Une courte visite de l'affichage et de chaque onglet des paramètres."
L["Replay The Welcome Tour"] = "Rejouer la visite de bienvenue"
L["Shows the welcome tour again: the display and every settings tab, one step at a time."] = "Montre à nouveau la visite de bienvenue : l'affichage et chaque onglet des paramètres, étape par étape."
L["not joined"] = "non rejoint"
L["You are not in the %s channel right now (Trade only works in cities)."] = "Vous n'êtes pas dans le canal %s en ce moment (Commerce ne fonctionne qu'en ville)."
L["Public channels: one share a minute. Try again shortly."] = "Canaux publics : un partage par minute. Réessayez dans un instant."
L["Closes the tour. You can replay it from the Share LazyGCore tab or with /lazygcore tour."] = "Ferme la visite. Vous pouvez la rejouer depuis l'onglet Partager LazyGCore ou avec /lazygcore tour."
L["Goes back to the previous step of the tour."] = "Revient à l'étape précédente de la visite."
L["Turn LazyGCore on or off, lock the display, pick the rotation engine and spec, choose when the display shows, and change its theme, skin and size. Hover over any option to see what it does."] = "Activez ou désactivez LazyGCore, verrouillez l'affichage, choisissez le moteur de recommandations et la spécialisation, quand l'affichage apparaît, ainsi que son thème, son apparence et sa taille. Survolez une option pour voir ce qu'elle fait."
L["Everything on the display: the main and cooldown icons, spell history and timeline, the action bar glow and the swing timer."] = "Tout ce qui concerne l'affichage : les icônes principale et de temps de recharge, l'historique et la frise des sorts, la surbrillance des barres d'action et le minuteur de coups."
L["What LazyGCore suggests (AoE, defensives, buffs and pets), the KICK!, DEFENSIVE! and PURGE alerts with their sounds, and Group Sync with your group."] = "Ce que LazyGCore suggère (zone, défensifs, améliorations et familiers), les alertes KICK!, DEFENSIVE! et PURGE avec leurs sons, et la synchro avec votre groupe."
L["Options for your own class, such as the Warlock curse, Rogue finishers or Mage mana gems."] = "Des options pour votre propre classe, comme la malédiction du démoniste, les coups de grâce du voleur ou les gemmes de mana du mage."
L["Ready-made macros for your class and spec (PvE and PvP), plus account macros for all your characters. One click creates them."] = "Des macros prêtes à l'emploi pour votre classe et votre spécialisation (JcE et JcJ), plus des macros de compte pour tous vos personnages. Un clic les crée."
L["Your DPS and HPS strip, the Stats window, GearScore, consumables, parse readiness and who else uses LazyGCore."] = "Votre bandeau DPS et HPS, la fenêtre de statistiques, le GearScore, les consommables, la préparation aux parses et qui d'autre utilise LazyGCore."
L["Build your own rotation, exclude spells you never want suggested, and turn LazyGCore off in chosen instances."] = "Créez votre propre rotation, excluez les sorts que vous ne voulez jamais voir suggérés et désactivez LazyGCore dans les instances choisies."
L["Update speed, troubleshooting tools and Reset all settings."] = "Vitesse de mise à jour, outils de dépannage et Réinitialiser tous les paramètres."
L["Save, load, copy and share your settings, or switch profiles automatically per spec."] = "Enregistrez, chargez, copiez et partagez vos paramètres, ou changez de profil automatiquement selon la spécialisation."
L["LazyGCore speaks six languages: English, German, Spanish, French, Japanese and Simplified Chinese. Pick one here, or keep Auto."] = "LazyGCore parle six langues : anglais, allemand, espagnol, français, japonais et chinois simplifié. Choisissez-en une ici ou gardez Auto."
L["What LazyGCore is and how it reads the game on Forever."] = "Ce qu'est LazyGCore et comment il lit le jeu sur Forever."
L["Type /lazygcore for the settings, /lazygcore help for every command. Replay this tour any time from the Share LazyGCore tab."] = "Tapez /lazygcore pour les paramètres, /lazygcore help pour toutes les commandes. Rejouez cette visite à tout moment depuis l'onglet Partager LazyGCore."

-- LazyGCore links (ShareLink)
L["%s Click it with LazyGCore Forever to use it - free on CurseForge: %s"] = "%s Cliquez dessus avec LazyGCore Forever pour l'utiliser - gratuit sur CurseForge : %s"
L["%s %s rotation"] = "rotation %s %s"
L["%s %s %s"] = "%s %s : %s"
L["Before %s's rotation"] = "Avant la rotation de %s"
L["No rotation to share for this spec."] = "Aucune rotation à partager pour cette spécialisation."
L["Share rotation"] = "Partager la rotation"
L["Posts a LazyGCore link to the build your Talent Guide follows, to the channel picked in Post to. Players with LazyGCore click it to follow the same build; everyone else sees where to get LazyGCore. Sent only when you click."] = "Publie un lien LazyGCore vers le build suivi par votre guide des talents, dans le canal choisi dans Publier dans. Les joueurs avec LazyGCore cliquent dessus pour suivre le même build ; les autres voient où obtenir LazyGCore. Envoyé uniquement quand vous cliquez."
L["Posts a LazyGCore link to your rotation for this spec (your custom list, or LazyGCore's default when you have none), to the channel picked in Post to. Players with LazyGCore click it to use it; everyone else sees where to get LazyGCore. Sent only when you click."] = "Publie un lien LazyGCore vers votre rotation pour cette spécialisation (votre liste personnalisée, ou celle de LazyGCore par défaut si vous n'en avez pas), dans le canal choisi dans Publier dans. Les joueurs avec LazyGCore cliquent dessus pour l'utiliser ; les autres voient où obtenir LazyGCore. Envoyé uniquement quand vous cliquez."
L["That is your own share."] = "C'est votre propre partage."
L["LazyGCore links open after combat."] = "Les liens LazyGCore s'ouvrent après le combat."
L["LazyGCore can't send right now (combat, a boss fight or PvP). Try again in a moment."] = "LazyGCore ne peut pas envoyer pour le moment (combat, boss ou JcJ). Réessayez dans un instant."
L["Already asking for that share..."] = "Demande de ce partage déjà en cours..."
L["That LazyGCore link doesn't work."] = "Ce lien LazyGCore ne fonctionne pas."
L["Asking %s for their LazyGCore share..."] = "Demande du partage LazyGCore à %s..."
L["%s didn't answer. They must be online, and a share lasts 2 hours (or until they reload)."] = "%s n'a pas répondu. Le joueur doit être en ligne, et un partage dure 2 heures (ou jusqu'à son rechargement)."
L["%s's share has expired. Ask them to share it again."] = "Le partage de %s a expiré. Demandez-lui de le partager à nouveau."
L["%s shared it for another class: it only works for that class."] = "%s l'a partagé pour une autre classe : il ne fonctionne que pour cette classe."
L["%s's share is for a spec LazyGCore doesn't know here."] = "Le partage de %s concerne une spécialisation que LazyGCore ne connaît pas ici."
L["%s's build isn't in your LazyGCore version. Update LazyGCore and try again."] = "Le build de %s n'est pas dans votre version de LazyGCore. Mettez LazyGCore à jour et réessayez."
L["%s's rotation has nothing your LazyGCore can use."] = "La rotation de %s ne contient rien que votre LazyGCore puisse utiliser."
L["%s's share couldn't be read."] = "Le partage de %s n'a pas pu être lu."
L["%s shared a %s rotation (%d spells: %s).\n\nUse it as your custom rotation? Your current list is kept as a saved rotation."] = "%s a partagé une rotation %s (%d sorts : %s).\n\nL'utiliser comme rotation personnalisée ? Votre liste actuelle est conservée comme rotation enregistrée."
L["Using %s's %s rotation. Change it any time on the Competitive tab."] = "Vous utilisez la rotation de %s (%s). Modifiez-la à tout moment dans l'onglet Compétitif."
L["Use it"] = "L'utiliser"
L["%s shared a %s build: %s.\n\nFollow it in your Talent Guide?"] = "%s a partagé un build %s : %s.\n\nLe suivre dans votre guide des talents ?"
L["Your Talent Guide now follows %s's %s build."] = "Votre guide des talents suit maintenant le build de %s (%s)."
L["Follow it"] = "Le suivre"
L["Share your rotation and build"] = "Partagez votre rotation et votre build"
L["Posts a LazyGCore link to the same channel. Players with LazyGCore click it to use your rotation or follow your talent build; everyone else sees where to get LazyGCore."] = "Publie un lien LazyGCore dans le même canal. Les joueurs avec LazyGCore cliquent dessus pour utiliser votre rotation ou suivre votre build de talents ; les autres voient où obtenir LazyGCore."
L["Scan with your phone to open LazyGCore Forever on CurseForge."] = "Scannez avec votre téléphone pour ouvrir LazyGCore Forever sur CurseForge."
L["Point your phone's camera at the code to open LazyGCore Forever on CurseForge."] = "Pointez l'appareil photo de votre téléphone sur le code pour ouvrir LazyGCore Forever sur CurseForge."
L["QR code"] = "Code QR"
L["Start here: share LazyGCore with friends in one click (party, guild, whisper or a channel like Trade), share your rotation or talent build as a LazyGCore link, send me suggestions or bug reports, and replay this tour."] = "Commencez ici : partagez LazyGCore avec vos amis en un clic (groupe, guilde, chuchotement ou un canal comme Commerce), partagez votre rotation ou votre build de talents en lien LazyGCore, envoyez-moi vos suggestions ou bugs, et rejouez cette visite."

LazyGCore.Locale:RegisterLocale("frFR", L)

-- 1.0.7 (16 Oct beta build)
L["Arcane Wrath"] = "Courroux des arcanes"
L["Presence of Mind: instant 3.5s Arcane Wrath."] = "Présence spirituelle : Courroux des arcanes de 3,5 s instantané."
L["Your hardest hit: scales with your maximum mana (6s cooldown)."] = "Votre coup le plus fort : augmente avec votre mana maximum (6 s de TR)."
L["Winter's Chill: +40% Cone of Cold damage per stack."] = "Froid hivernal : +40 % de dégâts de Cône de froid par cumul."
L["15s: faster Lightning Bolt and Lava Burst, Chain Lightning without a cooldown."] = "15 s : Éclair et Explosion de lave plus rapides, Chaîne d'éclairs sans temps de recharge."
L["Elemental Mastery: no cooldown on Chain Lightning."] = "Maîtrise élémentaire : Chaîne d'éclairs sans temps de recharge."

-- 1.0.7 (16 Oct beta build)
L["Nothing to press right now - keep attacking."] = "Rien à appuyer pour l'instant - continuez d'attaquer."
L["Enemy nameplates are off, so LazyGCore can't count the enemies around you and won't suggest AoE spells. Press V or type /lazygcore nameplates to turn them on."] = "Les barres de nom ennemies sont désactivées : LazyGCore ne peut pas compter les ennemis autour de vous et ne suggère pas de sorts de zone. Appuyez sur V ou tapez /lazygcore nameplates pour les activer."

-- 1.0.7 (16 Oct beta build)
L["Type /lazygcore reset confirm to reset all settings and reload the UI."] = "Tapez /lazygcore reset confirm pour réinitialiser tous les réglages et recharger l'interface."

-- 1.0.7 (16 Oct beta build)
L["Use it on your weapon."] = "Utilisez-la sur votre arme."

-- 1.0.7 (16 Oct beta build)
L["Before Demonic Pact: Searing Pain out-damages Shadow Bolt."] = "Avant Pacte démoniaque : Douleur brûlante inflige plus de dégâts que Trait de l'ombre."
L["Questing: free damage while you nuke."] = "En quête : des dégâts gratuits pendant que vous lancez vos sorts."

-- 1.0.7 (16 Oct beta build)
L["Can't change that in combat."] = "Impossible de changer cela en combat."
L["Enemy nameplates are on: LazyGCore can count the enemies around you for AoE."] = "Les barres de nom ennemies sont activées : LazyGCore peut compter les ennemis autour de vous pour les sorts de zone."
L["Turn on enemy nameplates (LazyGCore counts nearby enemies from them for AoE suggestions)"] = "Active les barres de nom ennemies (LazyGCore s'en sert pour compter les ennemis proches pour les suggestions de zone)"
L["Automatic AoE threshold"] = "Seuil de zone automatique"
L["Uses the best number of enemies for your spec, worked out by simulation (for example 2 for cleave specs). Turn it off to set your own number below. Only applies when Enable AoE suggestions is on."] = "Utilise le meilleur nombre d'ennemis pour votre spécialisation, calculé par simulation (par exemple 2 pour les spécialisations à frappe en arc). Désactivez-le pour choisir votre propre nombre ci-dessous. S'applique seulement si Activer les suggestions AoE est activé."

-- 1.0.7 (16 Oct beta build)
L["Sunder Armor as DPS"] = "Fracasser armure en DPS"
L["Arms and Fury: stack Sunder Armor to 5 against elites and in 5-player groups when nobody else applies it (a big damage gain). Leave it off when a tank or another warrior sunders. Never in raids"] = "Armes et Fureur : cumule Fracasser armure jusqu'à 5 contre les élites et en groupe de 5 quand personne d'autre ne l'applique (gros gain de dégâts). Laissez-le désactivé si un tank ou un autre guerrier l'applique. Jamais en raid"
L["Nobody else sunders: armor shred is worth more than your next hit."] = "Personne d'autre ne fracasse l'armure : la réduction d'armure vaut plus que votre prochain coup."

-- 1.0.7 (16 Oct beta build)
L["Improved Scorch: fast crits feed Heating Up."] = "Brûlure améliorée : des critiques rapides alimentent Heating Up."

-- 1.0.7 (16 Oct beta build)
L["Group: instant, shares Aimed Shot's cooldown."] = "Groupe : instantané, partage le TR de Visée."

-- 1.0.8
L["Rotation for"] = "Rotation pour"
L["Automatic"] = "Automatique"
L["Open world"] = "Monde ouvert"
L["Dungeon"] = "Donjon"
L["Usage: /lazygcore content auto | world | dungeon | raid"] = "Utilisation : /lazygcore content auto | world | dungeon | raid"
L["Show or set the content the rotation is for: auto, world (questing), dungeon or raid"] = "Affiche ou règle le contenu visé par la rotation : auto, world (quêtes), dungeon ou raid"
L["Which rotation to use (this character). Automatic: the open-world questing rotation outside instances, also when you quest in a party, the dungeon rotation in 5-player dungeons and the raid rotation in raids. Pick one to always use it. Also /lazygcore content."] = "Quelle rotation utiliser (ce personnage). Automatique : la rotation de quête du monde ouvert hors des instances, même en groupe, la rotation de donjon dans les donjons à 5 et la rotation de raid en raid. Choisissez-en une pour toujours l'utiliser. Aussi /lazygcore content."

-- 1.0.8
L["Out of mana: drink a mana potion."] = "Plus de mana : buvez une potion de mana."
L["Low health: drink a healing potion."] = "Vie basse : buvez une potion de soins."
L["Potions"] = "Potions"
L["Shows a mana potion on the cooldown icon once a fight has run you out of mana, and a healing potion below 35% health (the best potion in your bags, when its cooldown is ready)."] = "Affiche une potion de mana sur l'icône de temps de recharge dès qu'un combat vous a vidé de votre mana, et une potion de soins sous 35 % de vie (la meilleure potion de vos sacs, quand son temps de recharge est prêt)."
L["Your pet is not happy: feed it for full damage."] = "Votre familier n'est pas heureux : nourrissez-le pour qu'il inflige tous ses dégâts."

-- 1.0.8
L["Feed Pet"] = "Nourrir le familier"

-- 1.0.9
L["Playstyle"] = "Style de jeu"
L["Efficient"] = "Économe"
L["Balanced"] = "Équilibré"
L["Max damage"] = "Dégâts max"
L["Questing solo"] = "Quêtes en solo"
L["Questing in a group"] = "Quêtes en groupe"
L["Usage: /lazygcore style auto | efficient | balanced | max"] = "Utilisation : /lazygcore style auto | efficient | balanced | max"
L["Show or set the playstyle: auto, efficient (save mana and health), balanced or max (most damage)"] = "Affiche ou règle le style de jeu : auto, efficient (économise mana et vie), balanced ou max (dégâts maximum)"
L["How hard to push (this character). Efficient: saves mana and health - fewer breaks to drink and eat while questing, more mana left after each pull in groups. Balanced: the fastest leveling counting rest, and steady damage with a mana reserve in groups. Max damage: the most damage now - every mob dies as fast as possible, best for raid bosses and when a healer keeps you up. Automatic: Balanced while questing and in dungeons, Max damage in raids and PvP. Where the simulator found nothing better for your spec, two styles play the same. Also /lazygcore style."] = "Jusqu'où pousser (ce personnage). Économe : économise mana et vie - moins de pauses pour boire et manger en quête, plus de mana après chaque pull en groupe. Équilibré : la montée de niveau la plus rapide repos compris, et des dégâts réguliers avec une réserve de mana en groupe. Dégâts max : le plus de dégâts tout de suite - chaque monstre meurt au plus vite, idéal pour les boss de raid et quand un soigneur vous maintient en vie. Automatique : Équilibré en quête et en donjon, Dégâts max en raid et en JcJ. Quand le simulateur n'a rien trouvé de mieux pour votre spécialisation, deux styles jouent pareil. Aussi /lazygcore style."
L["Cheap nuke: more damage per mana here than the DoTs."] = "Sort peu coûteux : ici plus de dégâts par mana que les DoT."
-- 1.1.0 (launch changes)
L["Armor, +3% crit for your party or raid, double Omen procs."] = "Armure, +3 % de critique au groupe ou au raid, déclenchements d'Augure de clarté doublés."
L["Endgame PvE Cat (0/35/16)"] = "JcE fin de jeu Félin (0/35/16)"
L["Endgame PvE Bear (0/43/8)"] = "JcE fin de jeu Ours (0/43/8)"
L["PvP Cat Shifting Power (0/35/16)"] = "JcJ Félin Shifting Power (0/35/16)"
L["Leveling 10-60 (6/0/45)"] = "Montée en niveau 10-60 (6/0/45)"
L["Endgame PvE (6/0/45)"] = "JcE fin de jeu (6/0/45)"
L["Racial: +50% health and mana regeneration for 15s (+100% while Attuned)."] = "Raciale : +50 % de régénération de vie et de mana pendant 15 s (+100 % avec Harmonisé)."
