L["15s: faster Lightning Bolt, Chain Lightning without a cooldown."] = "15 s : Éclair plus rapide, Chaîne d'éclairs sans temps de recharge."
L["Totemic Call"] = "Appel totémique"
L["Leveling 10-60, Cruelty first (34/17/0)"] = "Montée en niveau 10-60, Cruauté d'abord (34/17/0)"
