L["Arcane Blast spell damage is up."] = "Les dégâts des sorts de Déflagration des arcanes sont actifs."
L["R3 with Ice Shards 5: beats Fireball."] = "R3 avec Éclats de glace 5 : surpasse Boule de feu."
L["Fingers of Frost: x4 damage + Shatter."] = "Doigts de givre : dégâts x4 + Fracasser."
L["Target is frozen: x4 damage."] = "La cible est gelée : dégâts x4."
L["Winter's Chill: +20% Cone of Cold damage per stack."] = "Froid hivernal : +20% de dégâts de Cône de froid par charge."
L["Shield up before the pull: +15% Frost damage for 1 min."] = "Bouclier avant le pull : +15% de dégâts de Givre pendant 1 min."
L["+15% Frost damage for 1 min (+5% while the shield holds)."] = "+15% de dégâts de Givre pendant 1 min (+5% tant que le bouclier tient)."
L["Arcane: Arcane Blast stacks to build on elites, bosses, groups and players before Arcane Wrath and Arcane Missiles. Each stack adds 12% of your Intellect as spell damage for 18 seconds from the first Blast, but makes the next Blast cost more (trash always gets one Blast)"] = "Arcanes : charges de Déflagration des arcanes à cumuler sur les élites, les boss, en groupe et contre les joueurs avant Courroux des arcanes et Projectiles des arcanes. Chaque charge ajoute 12% de votre Intelligence en dégâts des sorts pendant 18 secondes à partir de la première Déflagration, mais renchérit la suivante (les monstres normaux reçoivent toujours une Déflagration)"
L["Holy Binding: you and the target are both hurt."] = "Lien sacré : vous et la cible êtes tous deux blessés."
L["Instant; costs 30% HP if it survives."] = "Instantané ; coûte 30% des PV si la cible survit."
L["Shank"] = "Shank"
L["Death Mark"] = "Marque de mort"
L["Off-hand strike that gives Energy back - use on cooldown."] = "Frappe de main gauche qui rend de l'énergie - à utiliser dès que possible."
L["Energy back; with Venom +30% poison damage for 6s."] = "Rend de l'énergie ; avec Toxine, +30 % de dégâts des poisons pendant 6 s."
L["Energy back; with Boot Knife +2 CP."] = "Rend de l'énergie ; avec Couteau de botte, +2 PC."
L["Stores part of your damage for 6s, then deals it again (bleeds count double)."] = "Stocke une partie de vos dégâts pendant 6 s, puis les inflige à nouveau (les saignements comptent double)."
L["Long fight and Slice and Dice has time left."] = "Combat long et Débiter dure encore."
L["Improved Ambush crit (or after Ghostly Strike)."] = "Critique d'Embuscade améliorée (ou après Frappe fantomatique)."
