L["Your Rupture and Garrote deal +15% damage."] = "Votre Rupture et votre Garrot infligent +15 % de dégâts."
L["+15% dodge (feeds Setup); your next Ambush needs no Stealth."] = "+15 % d'esquive (alimente Préparatifs) ; votre prochaine Embuscade ne requiert pas le camouflage."
