-- 1.1.0 (launch changes)
L["Dungeons"] = "Donjons"
L["Raids"] = "Raids"
L["LazyGCore's picks"] = "Choix de LazyGCore"
L["LazyGCore's pick for:"] = "Choix de LazyGCore pour :"
L["Click to follow this build."] = "Cliquez pour suivre ce build."
L["Arms: a two-hander with Sweeping Strikes and Mortal Strike kills fast, and Improved Tactical Mastery keeps your Rage on stance swaps."] = "Armes : une arme à deux mains avec Frappes circulaires et Frappe mortelle tue vite, et Maîtrise tactique améliorée garde votre rage aux changements de posture."
L["Groups need tanks: Protection holds packs with Thunder Clap, Shield Slam and Revenge. Go Fury if you join as damage."] = "Les groupes ont besoin de tanks : Protection tient les packs avec Coup de tonnerre, Heurt de bouclier et Vengeance. Prenez Fureur si vous venez en DPS."
L["Fury: two weapons with Bloodthirst, Flurry and Whirlwind for the most boss damage. Raid tanks stay Protection."] = "Fureur : deux armes avec Sanguinaire, Rafale et Tourbillon pour le plus de dégâts sur les boss. Les tanks de raid restent Protection."
L["Arms: Mortal Strike halves the healing your target takes - the warrior pick for battlegrounds and duels."] = "Armes : Frappe mortelle réduit de moitié les soins reçus par votre cible - le choix du guerrier en champ de bataille et en duel."
L["Retribution: Seal of Command and Unsealed Wrath hit hard, and you heal yourself instead of resting."] = "Vindicte : Sceau d'autorité et Unsealed Wrath frappent fort, et vous vous soignez au lieu de vous reposer."
L["Protection: Consecration and Holy Shield hold whole packs. Holy if your group needs a healer."] = "Protection : Consécration et Bouclier sacré tiennent des packs entiers. Sacré si votre groupe a besoin d'un soigneur."
L["Holy: big, mana-efficient heals on the tanks with Holy Shock and Light's Vigil."] = "Sacré : de gros soins économes en mana sur les tanks avec Horion sacré et Light's Vigil."
L["Retribution: Seal of Command bursts and Repentance controls. Holy if you want to heal in battlegrounds."] = "Vindicte : Sceau d'autorité pour le burst et Repentir pour le contrôle. Sacré si vous voulez soigner en champ de bataille."
L["Beast Mastery: your pet tanks and Bestial Wrath kills fast - the easiest way to level."] = "Maîtrise des bêtes : votre familier tanke et Courroux bestial tue vite - la façon la plus simple de monter de niveau."
L["Marksmanship: steady ranged damage, Trueshot Aura for the group and Barrage on packs."] = "Précision : dégâts à distance réguliers, Aura de précision pour le groupe et Barrage sur les packs."
L["Marksmanship: the strongest sustained ranged damage, and Trueshot Aura helps the raid."] = "Précision : les plus gros dégâts à distance soutenus, et Aura de précision aide le raid."
L["Survival: Counterattack, Deterrence and Entrapment keep melee off you."] = "Survie : Contre-attaque, Dissuasion et Piège immobilisant tiennent les combattants au corps à corps à distance."
L["Combat: Sinister Strike, Shank and Adrenaline Rush with any weapon - fast kills, few deaths."] = "Combat : Attaque pernicieuse, Shank et Poussée d'adrénaline avec n'importe quelle arme - tue vite, meurt peu."
L["Combat: Blade Flurry is the best rogue damage on packs."] = "Combat : Déluge de lames donne les meilleurs dégâts de voleur sur les packs."
L["Assassination: Mutilate and the stronger launch poisons for steady boss damage."] = "Assassinat : Mutilation et les poisons renforcés au lancement pour des dégâts réguliers sur les boss."
L["Subtlety: Premeditation, Preparation and Death Mark for the hardest openers."] = "Finesse : Préméditation, Préparation et Marque de mort pour les ouvertures les plus fortes."
L["Shadow: Spirit Tap, DoTs and Mind Flay - very little drinking between fights."] = "Ombre : Connexion spirituelle, DoT et Fouet mental - très peu de pauses pour boire."
L["Holy: Prayer of Healing and Holy Nova keep a whole group up. Discipline works too."] = "Sacré : Prière de soins et Nova sacrée gardent tout le groupe en vie. Discipline fonctionne aussi."
L["Holy: the strongest group and raid healing."] = "Sacré : les soins de groupe et de raid les plus puissants."
L["Discipline: Penance, strong shields and Power Infusion. Shadow if you want damage."] = "Discipline : Pénitence, boucliers solides et Infusion de puissance. Ombre si vous voulez des dégâts."
L["Enhancement: Stormstrike every 8 seconds with Flurry and Windfury, and you heal yourself between pulls."] = "Amélioration : Frappe-tempête toutes les 8 secondes avec Rafale et Furie-des-vents, et vous vous soignez entre les pulls."
L["Restoration: Chain Heal and totems - groups always look for one."] = "Restauration : Salve de guérison et totems - les groupes en cherchent toujours un."
L["Restoration: Chain Heal and Mana Tide Totem, the shaman role raids want most."] = "Restauration : Salve de guérison et Totem de vague de mana, le rôle de chaman que les raids recherchent le plus."
L["Elemental: the stronger launch shocks give big burst. Restoration if you heal."] = "Élémentaire : les horions renforcés au lancement donnent un gros burst. Restauration si vous soignez."
L["Frost: slows and Frost Nova keep mobs off you; this build pulls whole packs from about 30."] = "Givre : ralentissements et Nova de givre tiennent les monstres à distance ; ce build attire des packs entiers dès le niveau 30 environ."
L["Frost: Blizzard and Cone of Cold on packs, and control when a pull goes wrong."] = "Givre : Blizzard et Cône de froid sur les packs, et du contrôle quand un pull tourne mal."
L["Fire: Ignite and Combustion for the most boss damage."] = "Feu : Enflammer et Combustion pour le plus de dégâts sur les boss."
L["Frost: Shatter combos, Ice Block and Ice Barrier."] = "Givre : combos Fracasser, Bloc de glace et Barrière de glace."
L["Affliction: DoTs and drains keep you topped up - almost no downtime."] = "Affliction : DoT et drains vous gardent en pleine forme - presque aucune pause."
L["Destruction: Shadow Bolt and Incinerate damage, Rain of Fire on packs."] = "Destruction : dégâts de Trait de l'ombre et Incinérer, Pluie de feu sur les packs."
L["Destruction: the most single-target damage."] = "Destruction : les plus gros dégâts sur cible unique."
L["Affliction: DoTs, fears and drains wear players down."] = "Affliction : DoT, peurs et drains usent les joueurs."
L["Feral: Cat Form kills fast, Bear Form saves bad pulls, Travel Form between quests."] = "Combat farouche : la forme de félin tue vite, la forme d'ours sauve les mauvais pulls, la forme de voyage entre les quêtes."
L["Feral Bear: tanks packs with Swipe and Lacerate. Restoration if you heal."] = "Ours farouche : tanke les packs avec Balayage et Lacérer. Restauration si vous soignez."
L["Restoration: HoTs, Wild Growth and Swiftmend - raids always want druid healers."] = "Restauration : HoT, Croissance sauvage et Prompte guérison - les raids veulent toujours des druides soigneurs."
L["Feral: shift out of roots and snares. Restoration is a strong battleground healer."] = "Combat farouche : changez de forme pour vous libérer des racines et ralentissements. Restauration est un excellent soigneur de champ de bataille."
-- 1.1.0 (launch changes)
L["following"] = "suivi"
L["click to follow"] = "cliquez pour suivre"
L["Not sure which build to take? Click the one for what you play next."] = "Vous hésitez sur le build ? Cliquez sur celui de ce que vous allez jouer."
-- 1.1.0 (launch changes)
L["The Talents page shows the next talent of your build and lets you pick another build. LazyGCore's picks tell you the best build for leveling, dungeons, raids and PvP - one click to follow. While the talent frame is open, your next talent glows."] = "La page Talents montre le prochain talent de votre build et vous permet d'en choisir un autre. Les choix de LazyGCore indiquent le meilleur build pour la montée en niveau, les donjons, les raids et le JcJ - un clic pour le suivre. Tant que la fenêtre des talents est ouverte, votre prochain talent brille."
-- 1.1.0 (launch changes)
L["I use LazyGCore Forever: it shows what to press next, the best talent build for leveling, dungeons, raids and PvP, and ready-made macros. Free on CurseForge: %s"] = "J'utilise LazyGCore Forever : il montre quoi lancer ensuite, le meilleur build de talents pour monter de niveau, les donjons, les raids et le JcJ, et des macros toutes prêtes. Gratuit sur CurseForge : %s"
L["Know someone who would like LazyGCore? Share it in one click: what to press next, the best talents for leveling, dungeons, raids and PvP, and ready-made macros."] = "Vous connaissez quelqu'un qui aimerait LazyGCore ? Partagez-le en un clic : quoi lancer ensuite, les meilleurs talents pour monter de niveau, les donjons, les raids et le JcJ, et des macros toutes prêtes."
-- 1.1.0 (launch changes)
L["LazyGCore links open after the boss fight."] = "Les liens LazyGCore s'ouvrent après le combat de boss."
L["LazyGCore links don't work inside battlegrounds and arenas."] = "Les liens LazyGCore ne fonctionnent pas en champ de bataille ni en arène."
L["The game is blocking addon messages right now. Try again in a moment."] = "Le jeu bloque les messages d'addons en ce moment. Réessayez dans un instant."
L["That player is offline, so their share can't be fetched."] = "Ce joueur est hors ligne, son partage ne peut donc pas être récupéré."
L["Too many messages at once. Try again in a few seconds."] = "Trop de messages à la fois. Réessayez dans quelques secondes."
L["The game didn't send the request. Try again in a moment."] = "Le jeu n'a pas envoyé la demande. Réessayez dans un instant."
-- 1.1.0 (launch changes)
L["Tip:"] = "Astuce :"
L["Dual Wield Specialization needs a weapon in your off hand."] = "Spécialisation Ambidextrie nécessite une arme en main gauche."
L["Two-Handed Weapon Specialization only works with a two-handed weapon."] = "Spécialisation Arme à deux mains ne fonctionne qu'avec une arme à deux mains."
L["Your Protection talents (Bastion, Shield Slam, Defiance) need a shield."] = "Vos talents Protection (Bastion, Heurt de bouclier, Défi) nécessitent un bouclier."
L["Weaponmaster gives no bonus with daggers or fist weapons."] = "Maître d'armes ne donne aucun bonus avec les dagues ou les armes de pugilat."
L["Holy Shield and your Protection talents need a shield."] = "Bouclier sacré et vos talents Protection nécessitent un bouclier."
L["Mutilate needs a dagger in each hand."] = "Mutilation nécessite une dague dans chaque main."
L["Hemorrhage and Ghostly Strike hit much harder with a dagger in your main hand."] = "Hémorragie et Frappe fantomatique frappent bien plus fort avec une dague en main droite."
L["Weapon tips"] = "Conseils d'armes"
L["Out of combat, a soft tip when your weapons don't suit your talents: a two-hander for Two-Handed Weapon Specialization, a shield for Protection, an off-hand weapon for Dual Wield Specialization, daggers for Mutilate. Also one chat line when you equip them. Never during a fight."] = "Hors combat, un conseil discret quand vos armes ne vont pas avec vos talents : une arme à deux mains pour Spécialisation Arme à deux mains, un bouclier pour Protection, une arme en main gauche pour Spécialisation Ambidextrie, des dagues pour Mutilation. Aussi une ligne de discussion quand vous les équipez. Jamais pendant un combat."
-- 1.1.0 (launch changes)
L["CD"] = "CD"
L["BUFF"] = "BUFF"
-- 1.1.0 (launch changes)
L["Damage trinket: use it with your cooldowns."] = "Bijou de dégâts : utilisez-le avec vos temps de recharge."
L["Shows a ready damage trinket in the cooldown slot in fights worth it (elites, dungeons and raids, players, 3+ enemies) - only trinkets whose use effect adds damage for your spec, never defensive or utility ones. Also your PvP trinket when you are stunned or feared (with Suggest defensives on)."] = "Affiche un bijou de dégâts prêt dans l'emplacement de recharge lors des combats qui le valent (élites, donjons et raids, joueurs, 3+ ennemis) - uniquement les bijoux dont l'effet d'utilisation ajoute des dégâts pour votre spécialisation, jamais les défensifs ou utilitaires. Aussi votre bijou JcJ quand vous êtes étourdi ou apeuré (avec Suggérer les défensifs activé)."
-- 1.1.0 (launch changes)
L["Your swings stored this Seal: swap now, the next hit fires the copies."] = "Vos coups ont stocké ce Sceau : changez maintenant, le prochain coup déclenche les copies."
-- 1.1.0 (launch changes)
L["Fury: two one-handers with Bloodthirst, Whirlwind and Flurry kill fastest while leveling. Arms before you can dual wield (20)."] = "Fureur : deux armes à une main avec Sanguinaire, Tourbillon et Rafale tuent le plus vite en montée de niveau. Armes avant de pouvoir manier deux armes (20)."
-- 1.1.0 (launch changes)
L["Arcane: Arcane Blast stacks with Arcane Power and Presence of Mind - the most boss damage, and mana that lasts the whole fight."] = "Arcanes : charges de Déflagration des arcanes avec Pouvoir des arcanes et Présence spirituelle - le plus de dégâts sur les boss, et du mana pour tout le combat."
-- 1.1.0 (launch changes)
L["Auto: each spec's own choice (Subtlety: Rupture on elites, groups and players; Assassination, Combat and leveling: Eviscerate only). Rupture: Rupture first whenever it is missing on a target above 35% health. Eviscerate: never Rupture"] = "Auto : le choix propre à chaque spécialisation (Finesse : Rupture sur les élites, groupes et joueurs ; Assassinat, Combat et montée en niveau : Éviscération uniquement). Rupture : Rupture en priorité dès qu'elle manque sur une cible au-dessus de 35 % de vie. Éviscération : jamais Rupture"
-- 1.1.0 (launch changes)
L["Show spells on cooldown"] = "Afficher les sorts en recharge"
L["In combat, when nothing is ready, the main icon shows the next spell that comes off cooldown, greyed out with its cooldown. Off: only spells you can press right now are shown."] = "En combat, quand rien n'est prêt, l'icône principale montre le prochain sort qui sort de recharge, grisé avec sa recharge. Désactivé : seuls les sorts que vous pouvez lancer maintenant sont affichés."
L["'Nothing to press' in combat"] = "'Rien à lancer' en combat"
L["In combat, when there is nothing to press right now, the main icon shows the LazyGCore logo and 'Nothing to press right now - keep attacking.' Off: the icon and the text stay empty instead."] = "En combat, quand il n'y a rien à lancer pour l'instant, l'icône principale affiche le logo de LazyGCore et 'Rien à lancer pour l'instant - continuez d'attaquer.' Désactivé : l'icône et le texte restent vides."
-- 1.1.3 (Warlock raid gear option)
L["Raid Gear"] = "Équipement de raid"
L["Full raid gear rotation"] = "Rotation équipement de raid complet"
L["Dungeons and raids only. Demonology skips Demonic Brand and the Decimation Soul Fire; Destruction skips Corruption on single targets. In full raid gear this is about 2% more damage on raid bosses, but less in pre-raid gear, so it is off by default"] = "Donjons et raids uniquement. Démonologie ignore Marque démoniaque et le Feu de l'âme de Décimation ; Destruction ignore Corruption sur une seule cible. En équipement de raid complet, environ 2% de dégâts en plus sur les boss de raid, mais moins en équipement pré-raid, donc désactivé par défaut"
-- 1.1.3 (welcome tour: your class)
L["LazyGCore for your %s"] = "LazyGCore pour la classe %s"
L["LazyGCore knows every spec of your class: the rotation, your buffs and reminders, and the talents that change what it suggests."] = "LazyGCore connaît chaque spécialisation de votre classe : la rotation, vos améliorations et rappels, et les talents qui changent ce qu'il suggère."
L["LazyGCore plays Arms, Fury and Protection with you: Sunder Armor stacks, Heroic Strike when you have rage to spare, threat when you tank, and Battle Shout kept up. It tips you when your weapon does not suit your talents, and LazyGCore's picks show the best build for leveling, dungeons, raids and PvP."] = "LazyGCore joue Armes, Fureur et Protection avec vous : cumuls de Fracasser armure, Frappe héroïque quand vous avez de la rage en trop, menace quand vous tankez et Cri de guerre toujours actif. Il vous prévient quand votre arme ne convient pas à vos talents, et les choix de LazyGCore montrent le meilleur build pour monter de niveau, les donjons, les raids et le JcJ."
L["LazyGCore plays Retribution, Protection and Holy with you: Seals and Judgements in the right order, Holy Shield and Consecration when you tank, and for Holy a heal target picked from your party or raid, plus Cleanse when someone has a debuff you can remove. It reminds you of your Blessing and tips you when your weapon does not suit your talents."] = "LazyGCore joue Vindicte, Protection et Sacré avec vous : Sceaux et Jugements dans le bon ordre, Bouclier sacré et Consécration quand vous tankez, et en Sacré une cible de soin choisie dans votre groupe ou raid, plus Epuration quand quelqu'un a un effet néfaste que vous pouvez dissiper. Il vous rappelle votre Bénédiction et vous prévient quand votre arme ne convient pas à vos talents."
L["LazyGCore plays Beast Mastery, Marksmanship and Survival with you: Hunter's Mark, Serpent Sting, Aimed Shot, Multi-Shot and your Hawks at the right time, and what to do when a mob reaches melee range. It reminds you about your pet and Mend Pet, and keeps the right Aspect up."] = "LazyGCore joue Maîtrise des bêtes, Précision et Survie avec vous : Marque du chasseur, Morsure de serpent, Visée, Flèches multiples et vos faucons au bon moment, et quoi faire quand un ennemi arrive au corps à corps. Il vous rappelle votre familier et Guérison du familier, et garde le bon Aspect actif."
L["LazyGCore plays Assassination, Combat and Subtlety with you: it builds combo points and picks the finisher - Slice and Dice, Rupture or Eviscerate - at the number of points you choose. It reminds you to apply poisons, can suggest Vanish for damage, and tips you when your weapons do not suit your talents."] = "LazyGCore joue Assassinat, Combat et Finesse avec vous : il accumule les points de combo et choisit le coup de grâce - Débiter, Rupture ou Eviscération - au nombre de points que vous choisissez. Il vous rappelle d'appliquer vos poisons, peut suggérer Disparition pour les dégâts et vous prévient quand vos armes ne conviennent pas à vos talents."
L["LazyGCore plays Shadow, Holy and Discipline with you. Shadow: Shadow Word: Pain, Mind Blast and Mind Flay in the right order, Shadow Word: Death at the health you choose, and Vampiric Embrace in raids. Holy and Discipline: a heal target picked from your party or raid and the right heal for it. It keeps Inner Fire and your buffs up."] = "LazyGCore joue Ombre, Sacré et Discipline avec vous. Ombre : Mot de l'ombre : Douleur, Attaque mentale et Fouet mental dans le bon ordre, Mot de l'ombre : Mort à la vie que vous choisissez et Etreinte vampirique en raid. Sacré et Discipline : une cible de soin choisie dans votre groupe ou raid et le bon soin pour elle. Il garde Feu intérieur et vos améliorations actifs."
L["LazyGCore plays Elemental, Enhancement and Restoration with you: totems (Call of the Elements before dungeon and raid pulls), your weapon imbue and Water or Lightning Shield kept up, and for Restoration a heal target picked from your party or raid, with Chain Heal when several people are hurt."] = "LazyGCore joue Elémentaire, Amélioration et Restauration avec vous : totems (Appel des éléments avant les pulls en donjon et en raid), votre enchantement d'arme et Bouclier d'eau ou de foudre toujours actifs, et en Restauration une cible de soin choisie dans votre groupe ou raid, avec Salve de guérison quand plusieurs personnes sont blessées."
L["LazyGCore plays Arcane, Fire and Frost with you: Arcane Blast stacks, Scorch stacks for Fire, and your procs. It watches your mana with Mana Gems and Evocation, keeps Arcane Intellect and your armor up, tips you when your weapon does not suit your talents, and the cooldown icon shows when burst cooldowns and damage trinkets are ready."] = "LazyGCore joue Arcanes, Feu et Givre avec vous : cumuls de Déflagration des arcanes, de Brûlure pour le Feu, et vos procs. Il surveille votre mana avec les gemmes de mana et Evocation, garde Intelligence des arcanes et votre armure actives, vous prévient quand votre arme ne convient pas à vos talents, et l'icône de recharge montre quand vos techniques de burst et vos bijoux de dégâts sont prêts."
L["LazyGCore plays Affliction, Demonology and Destruction with you: your Curse and Bane, Corruption and Immolate refreshed at the right time, and the filler that suits your talents. It suggests Life Tap when you run low on mana, reminds you to summon your demon and keep Demon Armor and your weapon stone up, and suggests Health Funnel when your demon is hurt."] = "LazyGCore joue Affliction, Démonologie et Destruction avec vous : votre Malédiction et Fléau, Corruption et Immolation renouvelés au bon moment, et le sort de remplissage adapté à vos talents. Il suggère Connexion quand vous manquez de mana, vous rappelle d'invoquer votre démon et de garder Armure démoniaque et votre pierre d'arme actives, et suggère Captation de vie quand votre démon est blessé."
L["LazyGCore follows your form: Balance with Moonkin Form, Faerie Fire, Moonfire and Insect Swarm; Feral as a cat for damage or a bear for tanking; Restoration with a heal target picked from your party or raid and Rejuvenation kept rolling. It keeps Mark of the Wild and Thorns up."] = "LazyGCore suit votre forme : Equilibre avec Forme de sélénien, Lucioles, Eclat lunaire et Essaim d'insectes ; Farouche en félin pour les dégâts ou en ours pour tanker ; Restauration avec une cible de soin choisie dans votre groupe ou raid et Récupération toujours active. Il garde Marque du fauve et Epines actifs."

-- 1.1.4 (keybind size)
L["Custom keybind size"] = "Taille de raccourci personnalisée"
L["Lets you change the size of the keybind text on the main icon with Keybind Size. Off: the normal size that follows the icon size. Only applies when Show keybind is on."] = "Permet de changer la taille du texte du raccourci sur l'icône principale avec Taille du raccourci. Désactivé : la taille normale, qui suit la taille de l'icône. S'applique uniquement si Afficher le raccourci est activé."
L["Keybind Size"] = "Taille du raccourci"
L["Size of the keybind text compared to normal (1.50 = 50% bigger). Up to 4 fills the whole icon; a big keybind moves to the centre. It never grows past the icon: a long keybind shrinks to fit. Only applies when Custom keybind size is on."] = "Taille du texte du raccourci par rapport à la normale (1.50 = 50% plus grand). Jusqu'à 4, il remplit toute l'icône ; un grand raccourci passe au centre. Il ne dépasse jamais l'icône : un raccourci long est réduit pour tenir. S'applique uniquement si Taille de raccourci personnalisée est activé."

-- 1.1.5 (talent pick order)
L["Show the pick order on the talent frame"] = "Afficher l'ordre sur la fenêtre des talents"
L["Puts a number on every talent of your build that still needs points, in the order to take them (1 = next), on all trees, even when you have no point to spend."] = "Place un numéro sur chaque talent de votre build qui demande encore des points, dans l'ordre où les prendre (1 = le prochain), sur tous les arbres, même sans point à dépenser."
L["Pick numbers"] = "Numéros d'ordre"
L["How many upcoming talents get a number: the whole build (default) or only the next 3, 5 or 10. Only applies when Show the pick order on the talent frame is on."] = "Combien de talents à venir reçoivent un numéro : tout le build (par défaut) ou seulement les 3, 5 ou 10 prochains. S'applique uniquement si Afficher l'ordre sur la fenêtre des talents est activé."
L["Whole build"] = "Tout le build"
L["Next 3"] = "3 prochains"
L["Next 5"] = "5 prochains"
L["Next 10"] = "10 prochains"
